INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','Does JavaScript pass arguments by value or by reference?','JavaScript is **always call by value** — but for objects the value copied is a *reference* (a pointer). So reassigning a parameter never affects the caller, while mutating an object parameter''s properties does, because both names point to the same underlying object. This model is sometimes called "call by sharing".','If JS is ''call by value'', why does mutating an object argument change the original?','Because the value copied is the reference itself — the caller''s variable and the parameter point to the same object, so `obj.x = 1` is visible to both. Reassigning the parameter (`obj = {}`) only rebinds the local copy, leaving the caller untouched.','intermediate',ARRAY['references','primitives','memory','objects']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='Does JavaScript pass arguments by value or by reference?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','How does JavaScript use the stack and the heap to store data?','The **stack** holds execution frames and fixed-size primitive values — it''s fast, LIFO, and unwound automatically. The **heap** stores dynamically-sized objects, arrays, and functions; a variable on the stack holds a *reference* into the heap. That''s why primitives are copied by value while objects are shared by reference.','Where is a variable that holds an object stored — stack or heap?','Both, in a sense: the object''s data lives on the heap, while the variable (a reference/pointer to that object) lives on the stack. Copying the variable copies only the pointer, not the object — which is the mechanism behind shared mutable references.','intermediate',ARRAY['memory','stack','heap','references']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='How does JavaScript use the stack and the heap to store data?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is immutability, and why does it matter in JavaScript?','Immutability means not changing data in place; instead you produce a new copy with the change (`{...obj, k: v}`, `[...arr, x]`). It prevents bugs from shared mutable references, makes state changes explicit and traceable, enables cheap equality checks by reference, and underpins React/Redux change detection.','Does `const` make a value immutable?','No — `const` only prevents *reassigning the binding*. The value can still be mutated: `const a = []; a.push(1)` is legal. True immutability needs `Object.freeze`, a library like Immer, or the discipline of only ever creating copies.','intermediate',ARRAY['immutability','references','state-management','const']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is immutability, and why does it matter in JavaScript?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is type coercion in JavaScript?','The automatic conversion of a value from one type to another. **Implicit** coercion happens inside operations (`"5" * 2` → `10`, `1 + "2"` → `"12"`, `if ([])`); **explicit** coercion is deliberate (`Number(x)`, `String(x)`, `Boolean(x)`). The `+` operator prefers string concatenation if either side is a string; other arithmetic operators coerce to numbers.','What does `[] + {}` evaluate to, and why?','`"[object Object]"`. `+` converts both operands to primitives: `[]` becomes `""` and `{}` becomes `"[object Object]"`, so the result is their concatenation. (Reversed, `{} + []` can be `0` at the start of a statement, because `{}` is then parsed as a block rather than an object.)','intermediate',ARRAY['type-coercion','type-conversion','operators','equality']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is type coercion in JavaScript?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a higher-order function?','A function that takes one or more functions as arguments and/or returns a function. Examples: `Array.prototype.map`/`filter`/`reduce`, `setTimeout`, and function factories. They are the foundation of composition, callbacks, currying, and decorators in JavaScript.','Write a higher-order function `multiplier` so that `multiplier(2)(5)` returns `10`.','`const multiplier = (factor) => (n) => n * factor;`. `multiplier` returns a new function that closes over `factor`, so `multiplier(2)` yields `n => n * 2`, and calling it with `5` gives `10`.','beginner',ARRAY['higher-order-functions','functional-programming','closures','callbacks']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a higher-order function?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between the spread and rest operators (`...`)?','Same `...` token, opposite jobs. **Spread** *expands* an iterable or object into individual elements: `[...arr]`, `{...obj}`, `fn(...args)`. **Rest** *collects* remaining items into an array: `function f(a, ...rest)`, `const [first, ...others] = arr`. Spread appears in call/literal positions; rest appears in parameter/destructuring positions.','In `const [a, ...b] = [1, 2, 3]`, is `...b` spread or rest — and what is `b`?','It''s **rest** (it sits in a destructuring target, collecting values), so `b` is `[2, 3]`. Rest gathers the leftover elements into a real array and must be the last element.','beginner',ARRAY['spread','rest','destructuring','es6']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between the spread and rest operators (`...`)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between a shallow copy and a deep copy?','A **shallow copy** duplicates only the top level; nested objects/arrays stay shared by reference (`{...obj}`, `Object.assign({}, obj)`, `arr.slice()`). A **deep copy** recursively clones every level, so no references are shared and mutating the copy never affects the original.','What are the tradeoffs of `JSON.parse(JSON.stringify(obj))` for deep cloning?','Simple and universal but lossy: it drops `undefined`, functions, and symbols; turns `Date` into a string and `NaN`/`Infinity` into `null`; can''t handle `Map`/`Set`; and throws on circular references. `structuredClone(obj)` is the modern built-in that handles most of these (still no functions).','intermediate',ARRAY['shallow-copy','deep-copy','references','cloning']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between a shallow copy and a deep copy?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between `Object.freeze` and `Object.seal`?','**`Object.seal`** prevents *adding or deleting* properties but still lets you modify existing property values. **`Object.freeze`** does everything seal does *and* makes existing properties read-only (non-writable). Both are **shallow** — nested objects remain mutable.','How would you make an object deeply immutable?','Recursively freeze it (a "deep freeze"): walk every property and call `Object.freeze` on each nested object before/after freezing the parent. Plain `Object.freeze` only locks the top level, so nested structures stay mutable unless you recurse — or use a library like Immer.','intermediate',ARRAY['immutability','objects','object-freeze']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between `Object.freeze` and `Object.seal`?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','When should you use a `Map` instead of a plain object?','Use a **`Map`** when you need keys of any type (objects/functions, not just strings/symbols), guaranteed insertion order, a reliable `.size`, or frequent additions/deletions (Maps are optimized for that). Use a **plain object** for simple string-keyed records, JSON serialization, or method/prototype structure. A Map also has no inherited keys from the prototype chain.','Why can using a plain object as a hash map be risky?','Its prototype contributes inherited keys (`toString`, `constructor`, `__proto__`), so a user-supplied key like `"toString"` can collide or `"__proto__"` can corrupt the prototype. `Map` has no such keys; if you must use an object, `Object.create(null)` makes a prototype-less one.','intermediate',ARRAY['map','objects','data-structures','hash-map']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='When should you use a `Map` instead of a plain object?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a `Set`, and when would you use it over an array?','A **`Set`** is a collection of *unique* values with average O(1) `add`, `has`, and `delete`. Prefer it when you need uniqueness or fast membership tests — `set.has(x)` beats `arr.includes(x)`, which is O(n). Arrays keep duplicates, are indexable, and carry the full transform API (`map`, `filter`, `reduce`).','How do you deduplicate an array using a Set?','`[...new Set(arr)]` — building the Set drops duplicates, then spread converts it back to an array. Note it uses SameValueZero equality, so it dedupes primitives but treats two distinct objects as unique even when structurally identical.','intermediate',ARRAY['set','arrays','data-structures','deduplication']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a `Set`, and when would you use it over an array?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between `for...of` and `for...in`?','**`for...in`** iterates over enumerable *property keys*, including inherited ones — best for plain objects. **`for...of`** iterates over the *values* of an iterable (arrays, strings, `Map`, `Set`, generators). For arrays, prefer `for...of`; `for...in` yields string indices and can pick up extra enumerable properties.','Why can `for...in` over an array be a bug?','It iterates keys as *strings* ("0", "1", …), skips holes, doesn''t guarantee numeric order in every case, and includes any enumerable properties added to the array or `Array.prototype`. Use `for...of`, `forEach`, or a classic index loop for arrays.','intermediate',ARRAY['loops','iteration','iterables','arrays']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between `for...of` and `for...in`?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','Contrast `Promise.all`, `Promise.race`, `Promise.any`, and `Promise.allSettled`.','- **`all`**: resolves with an array of every result once all fulfill; rejects immediately if *any* rejects.
- **`race`**: settles as soon as the *first* promise settles — fulfilled *or* rejected.
- **`any`**: fulfills with the first *fulfillment*; rejects only if *all* reject (with an `AggregateError`).
- **`allSettled`**: waits for all and never rejects — returns each outcome as `{status, value|reason}`.','You need results from all requests but don''t want one failure to lose the rest. Which do you use?','`Promise.allSettled` — it waits for every promise and reports each as fulfilled or rejected without short-circuiting, so a single failure doesn''t discard the successful results the way `Promise.all` would.','intermediate',ARRAY['promises','async','concurrency','error-handling']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='Contrast `Promise.all`, `Promise.race`, `Promise.any`, and `Promise.allSettled`.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between debouncing and throttling?','Both limit how often a function runs during rapid events. **Debounce** delays execution until activity has *stopped* for N ms, so only the last call in a burst fires — ideal for search-as-you-type. **Throttle** guarantees at most one execution every N ms *during* continuous activity — ideal for scroll, mousemove, or rate-limited handlers.','For a ''save draft as the user types'' feature, which do you pick and why?','Debounce — you want to save once the user *pauses* typing, not on every keystroke, so waiting for a quiet gap (e.g. 500 ms) minimizes writes. Throttle would keep firing mid-typing, saving incomplete input more often than necessary.','intermediate',ARRAY['debounce','throttle','performance','events']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between debouncing and throttling?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is event delegation and why is it useful?','Attaching a single listener to a common ancestor and using `event.target` to handle events from many children, rather than binding a listener to each child. It relies on event **bubbling**. Benefits: fewer listeners (less memory) and automatic handling of elements added to the DOM *after* the listener was attached.','In a delegated handler, what''s the difference between `event.target` and `event.currentTarget`?','`event.target` is the element that actually triggered the event (the specific child); `event.currentTarget` is the element the listener is attached to (the ancestor). In delegation you inspect `target` — often via `target.closest(''.item'')` — to identify which child was interacted with.','intermediate',ARRAY['event-delegation','event-bubbling','dom','events']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is event delegation and why is it useful?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between event bubbling and capturing?','They are the two directions of DOM event propagation. **Capturing** (phase 1) travels *down* from the root to the target; **bubbling** (phase 3) travels back *up* from the target to the root. Listeners default to the bubbling phase; pass `{ capture: true }` to `addEventListener` to listen during capture. `event.stopPropagation()` halts further travel.','A parent and its child both have click listeners. In what order do they fire by default?','Child first, then parent — default listeners run in the bubbling phase (target → up). If the parent''s listener were registered with `capture: true`, it would fire *before* the child, because capturing goes top → down.','intermediate',ARRAY['event-bubbling','event-capturing','dom','events']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between event bubbling and capturing?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is CORS and what problem does it solve?','**Cross-Origin Resource Sharing** is an HTTP-header mechanism that lets a server *relax* the same-origin policy so a browser will let a page read responses from a different origin. The server opts in via headers like `Access-Control-Allow-Origin`. Without matching headers the browser blocks JS from *reading the response* — though the request may still have reached the server.','What is a CORS preflight request and when is it sent?','An automatic `OPTIONS` request the browser sends *before* a "non-simple" cross-origin request (custom headers, methods like `PUT`/`DELETE`, or certain content types) to ask permission. The server must answer with `Access-Control-Allow-Methods`/`-Headers`; only then is the real request sent.','intermediate',ARRAY['cors','security','http','same-origin-policy']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is CORS and what problem does it solve?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the same-origin policy?','A browser security rule restricting how a document/script from one **origin** can interact with resources from another. An origin is the tuple **scheme + host + port** — all three must match. It blocks reading cross-origin responses, cross-origin DOM access across iframes, and access to another origin''s cookies/storage, limiting cross-site data theft.','Are `https://site.com` and `https://site.com:8443` the same origin?','No — the port differs (default 443 vs 8443), and origin is scheme + host + **port**, so they''re cross-origin. Likewise `http://` vs `https://` (scheme) and `app.site.com` vs `site.com` (host) are each cross-origin.','intermediate',ARRAY['same-origin-policy','security','cors','browser']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the same-origin policy?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','When would you use IndexedDB instead of localStorage?','Use **IndexedDB** for large, structured, or binary data: it''s an asynchronous, transactional NoSQL database that stores objects and Blobs, with indexes and hundreds of MB of quota. **localStorage** is a tiny (~5 MB), synchronous, string-only key-value store — fine for small flags/preferences but it blocks the main thread and can''t hold complex data efficiently.','Why can heavy use of localStorage hurt performance?','It''s **synchronous** — every read/write blocks the main thread, so serializing/parsing large JSON strings janks the UI. IndexedDB is asynchronous (events/promises), so large operations run without blocking rendering.','intermediate',ARRAY['indexeddb','localstorage','storage','browser']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='When would you use IndexedDB instead of localStorage?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a service worker?','A script the browser runs in the background, separate from the page, acting as a programmable **network proxy** between the app and the network. It can intercept `fetch` requests, serve from a cache (offline support), handle push notifications, and do background sync. It has no DOM access, is event-driven, and requires HTTPS.','Why must service workers be served over HTTPS?','Because a worker can intercept and rewrite every network request within its scope — a powerful man-in-the-middle capability. Requiring HTTPS (localhost is exempted for development) stops an attacker on the network from injecting a malicious worker.','intermediate',ARRAY['service-workers','pwa','caching','offline']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a service worker?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What are Web Workers and what are they for?','Web Workers run JavaScript on a **background thread**, separate from the main UI thread, so CPU-heavy work (parsing, image processing, computation) doesn''t block rendering or input. They have no DOM/`window` access and communicate with the main thread by message passing (`postMessage`/`onmessage`), which copies data via structured clone rather than sharing it.','How do you share large data with a worker without the cost of copying it?','Use **transferable objects** — pass an `ArrayBuffer` (or its typed array) as the second `postMessage` argument to *transfer* ownership instead of cloning, which is near-instant (the sender loses access). `SharedArrayBuffer` goes further, giving true shared memory between threads.','intermediate',ARRAY['web-workers','concurrency','performance','threads']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What are Web Workers and what are they for?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between WebSocket and HTTP?','**HTTP** is a stateless request/response protocol — the client asks, the server answers, and the connection typically closes. **WebSocket** is a persistent, **full-duplex** connection (opened via an HTTP `Upgrade` handshake) where client and server can push messages to each other at any time with low overhead. Use WebSocket for realtime (chat, live feeds, games); HTTP for standard fetches.','How is a WebSocket connection established?','It starts as a normal HTTP request carrying an `Upgrade: websocket` header (the handshake). If the server agrees (`101 Switching Protocols`), the same TCP connection is repurposed for the bidirectional WebSocket protocol — so it reuses port 80/443 and traverses most proxies and firewalls.','intermediate',ARRAY['websocket','http','realtime','networking']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between WebSocket and HTTP?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is prototypal inheritance in JavaScript?','Objects inherit directly from other objects through an internal link (`[[Prototype]]`, exposed as `__proto__`). When you access a property, the engine walks the **prototype chain** — from the object up through its prototypes — until it finds the property or hits `null`. This is how shared methods (e.g. `Array.prototype.map`) are reused without copying them onto every instance.','What is the difference between an object''s `__proto__` and a function''s `prototype`?','`prototype` is a property on *constructor functions* — the object that becomes the `[[Prototype]]` of instances made with `new`. `__proto__` is the actual `[[Prototype]]` link present on *every* object, pointing to what it inherits from. Hence `new Foo().__proto__ === Foo.prototype`.','intermediate',ARRAY['prototypes','inheritance','prototype-chain','objects']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is prototypal inheritance in JavaScript?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is currying?','Transforming a function that takes multiple arguments into a sequence of functions that each take one: `f(a, b, c)` becomes `f(a)(b)(c)`. Each call returns a new function (via closures) that remembers the earlier arguments until all are supplied. It enables partial application and reusable, specialized functions.','What''s the difference between currying and partial application?','Currying always decomposes a function into a chain of *unary* calls: `f(a)(b)(c)`. Partial application fixes *some* arguments and returns a function taking the rest in any grouping: `f.bind(null, a)` yields a function still taking `(b, c)` together. Currying is a specific, fully-decomposed form of partial application.','intermediate',ARRAY['currying','functional-programming','closures','partial-application']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is currying?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is memoization?','A caching optimization: store the result of an expensive function call keyed by its arguments, and return the cached value when the same inputs recur instead of recomputing. It trades memory for speed and is only safe for **pure** functions (same input → same output). Common uses: expensive calculations, recursive algorithms, and React''s `useMemo`.','Why does memoization only work correctly on pure functions?','It assumes the same inputs always produce the same output. If the function has side effects or depends on external mutable state, a cached return would be stale or would skip the side effect — producing wrong behavior. Purity guarantees the cached value stays valid.','intermediate',ARRAY['memoization','caching','performance','pure-functions']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is memoization?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a generator function in JavaScript?','A function declared with `function*` that can **pause and resume**. Calling it returns an iterator; each `yield` produces a value and suspends execution until `.next()` is called again. `yield` can also *receive* a value passed into `.next(value)`. Generators power lazy/infinite sequences, custom iterables, and cooperative control flow.','How do generators enable lazy evaluation or infinite sequences?','Because execution suspends at each `yield` and resumes only on the next `.next()`, values are produced on demand rather than all upfront. You can write `while (true) yield n++` for an infinite sequence and consume only what you need — code past a `yield` never runs until requested, using no memory for un-requested values.','advanced',ARRAY['generators','iterators','lazy-evaluation','es6']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a generator function in JavaScript?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What are `WeakMap` and `WeakSet`, and how do they differ from `Map`/`Set`?','They hold **weak references** to their keys (WeakMap) or values (WeakSet), which must be *objects*. If nothing else references that object, it can be garbage-collected even while still in the WeakMap/WeakSet — avoiding leaks. Because entries can vanish, they are not iterable and have no `.size`. Ideal for attaching private/metadata to objects without blocking their cleanup.','Why can''t you iterate a WeakMap or read its size?','Its entries are subject to garbage collection at unpredictable times, so the contents aren''t deterministic or enumerable. Exposing iteration or `size` would leak GC timing and could return different results moment to moment — that''s the tradeoff for not preventing collection of its keys.','advanced',ARRAY['weakmap','weakset','garbage-collection','memory']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What are `WeakMap` and `WeakSet`, and how do they differ from `Map`/`Set`?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is tail call optimization (TCO)?','An engine optimization where a call in **tail position** (the very last action, whose result is returned directly) reuses the current stack frame instead of pushing a new one. This lets properly tail-recursive functions run in constant stack space, avoiding "Maximum call stack size exceeded". It''s specified in ES6 but, in practice, only shipped by JavaScriptCore/Safari — V8 (Chrome/Node) does not implement it.','Is `return n * factorial(n - 1)` a tail call?','No — the recursive call isn''t the last operation; its result is still multiplied by `n` afterward, so the frame must stay on the stack. A tail-recursive version threads an accumulator: `return factorial(n - 1, acc * n)`, where the call *is* the final action.','advanced',ARRAY['tail-call-optimization','recursion','call-stack','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is tail call optimization (TCO)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is the difference between CommonJS and ES modules?','**CommonJS** (`require`/`module.exports`, Node''s legacy system) loads modules *synchronously* at runtime and exports a value snapshot. **ES Modules** (`import`/`export`) are *statically analyzable*, loaded asynchronously, and export **live bindings** (importers see later updates to the exported variable). ESM''s static structure enables tree-shaking; `import` is hoisted and can''t be called conditionally like `require`.','What does it mean that ES modules export ''live bindings''?','Importers receive a read-only *reference* to the exported variable, not a one-time copy. If the module later reassigns that variable, importers see the new value. With CommonJS, `require` returns the value at import time, so a later reassignment inside the module isn''t reflected in what was already required.','intermediate',ARRAY['modules','commonjs','es-modules','tree-shaking']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is the difference between CommonJS and ES modules?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is dynamic `import()` and when would you use it?','A function-like form of `import` that loads a module **on demand at runtime** and returns a **promise** for the module namespace: `const mod = await import(''./chart.js'')`. Unlike static `import` (hoisted, top-level only), it can run conditionally, inside functions, or with a computed path. It underpins **code splitting** and lazy loading (e.g. React''s `lazy`), shrinking the initial bundle.','How does dynamic `import()` differ from static `import`?','Static `import` is resolved at parse time, hoisted, must be top-level, and takes a literal path — enabling tree-shaking. Dynamic `import()` runs at runtime, returns a promise, can be called conditionally or in loops with a dynamic path, and produces a separate chunk that loads only when reached.','intermediate',ARRAY['dynamic-import','code-splitting','modules','lazy-loading']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is dynamic `import()` and when would you use it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a polyfill?','Code that *implements* a modern feature in environments that lack it, so your code can use that feature everywhere. It typically checks whether the native feature exists and, if not, defines it — e.g. providing `Array.prototype.includes` or a `fetch` implementation for legacy browsers. Polyfills add runtime behavior, unlike transpilers which only rewrite syntax.','What''s the difference between a polyfill and a transpiler?','A **transpiler** (Babel) rewrites new *syntax* into older equivalent syntax at build time (arrow functions → `function`). A **polyfill** supplies missing *runtime APIs/methods* (`Promise`, `Array.from`) that can''t be produced by syntax transformation. Full legacy support often needs both.','beginner',ARRAY['polyfill','transpiler','browser-compatibility','babel']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a polyfill?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is a transpiler, and what does Babel do?','A transpiler (source-to-source compiler) converts code from one version/language into an equivalent form another environment understands. **Babel** compiles modern JS (ES2015+, JSX) down to backwards-compatible JavaScript older browsers can run — transforming *syntax* like arrow functions, classes, and optional chaining.','Can Babel alone make `Promise` work in an old browser?','No — Babel transforms *syntax*, but `Promise` is a missing *runtime API*, not syntax. You need a **polyfill** (e.g. via `core-js`, which Babel''s `preset-env` can inject automatically) to actually provide `Promise` in environments that lack it.','beginner',ARRAY['transpiler','babel','polyfill','build-tools']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is a transpiler, and what does Babel do?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','Why does `typeof null` return `''object''`?','It''s a **legacy bug** from the very first JavaScript implementation, kept for backward compatibility. Values were tagged by a type bit-pattern in their low bits; objects used tag `000`, and `null` was the machine NULL pointer (all-zero bits), so `typeof` read it as the object tag. A proposed fix was rejected because it would break existing code.','So how do you reliably check for `null`?','Compare directly: `value === null`. To check "is this a non-null object", use `typeof value === ''object'' && value !== null`. Don''t rely on `typeof` alone, since it lumps `null` in with objects.','intermediate',ARRAY['typeof','null','type-checking','quirks']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='Why does `typeof null` return `''object''`?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is `NaN`, and what are its notable quirks?','`NaN` ("Not-a-Number") is a numeric value representing an invalid or undefined math result (`0/0`, `Number("x")`, `Math.sqrt(-1)`). Its quirks: it is the only value **not equal to itself** (`NaN === NaN` is `false`), `typeof NaN` is `"number"`, and it propagates — any arithmetic involving `NaN` yields `NaN`.','How do you reliably test whether a value is `NaN`?','Use `Number.isNaN(x)`, which is true only for the actual `NaN` value. Avoid the global `isNaN(x)`, which first *coerces* its argument, so `isNaN("foo")` is `true` even though `"foo"` isn''t `NaN`. The trick `x !== x` also isolates `NaN`, since only `NaN` is unequal to itself.','intermediate',ARRAY['nan','numbers','type-coercion','quirks']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is `NaN`, and what are its notable quirks?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is `BigInt` and when do you need it?','A primitive type for integers of **arbitrary precision**, written with an `n` suffix (`123n`) or `BigInt(123)`. Use it when values exceed `Number.MAX_SAFE_INTEGER` (2^53 − 1) — large IDs, nanosecond timestamps, cryptography — where regular numbers silently lose precision because `Number` is a 64-bit float.','What happens if you evaluate `10n + 5`?','It throws a `TypeError` — you can''t mix `BigInt` and `Number` in arithmetic, since implicit conversion could lose precision. Convert explicitly: `10n + BigInt(5)` or `Number(10n) + 5`. (Comparisons do work across types, so `10n == 10` and `10n < 5` are fine.)','intermediate',ARRAY['bigint','numbers','primitives','precision']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is `BigInt` and when do you need it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What do optional chaining (`?.`) and nullish coalescing (`??`) do?','**`?.`** safely accesses a nested property/method/index and short-circuits to `undefined` if the value before it is `null`/`undefined`, instead of throwing: `user?.address?.city`, `arr?.[0]`, `fn?.()`. **`??`** returns its right operand only when the left is `null`/`undefined`, otherwise the left — ideal for defaults that must preserve valid falsy values like `0` or `""`.','Why use `??` instead of `||` for a default value?','`||` falls back on *any* falsy value, so `count || 10` wrongly returns `10` when `count` is `0`, and `name || ''x''` overrides an empty string. `??` falls back only on `null`/`undefined`, so `0 ?? 10` correctly stays `0`. Use `??` when `0`, `""`, or `false` are legitimate values.','beginner',ARRAY['optional-chaining','nullish-coalescing','es2020','null']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What do optional chaining (`?.`) and nullish coalescing (`??`) do?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'JavaScript','What is cross-site scripting (XSS) and how do you prevent it?','XSS is an injection attack where an attacker gets malicious JavaScript to run in another user''s browser in your site''s context, letting it steal cookies/tokens, hijack sessions, or deface the page. Prevention: **escape/encode** untrusted data on output, avoid `innerHTML`/`dangerouslySetInnerHTML` with user input (use `textContent`), sanitize HTML (e.g. DOMPurify), and set a **Content-Security-Policy**.','What''s the difference between stored, reflected, and DOM-based XSS?','**Stored** XSS persists the payload on the server (e.g. a malicious comment) and serves it to every viewer. **Reflected** XSS bounces the payload off the server from the request (e.g. a crafted URL) to one victim. **DOM-based** XSS never touches the server — untrusted input like `location.hash` is written into the DOM unsafely entirely on the client.','intermediate',ARRAY['xss','security','sanitization','csp']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='JavaScript' AND q='What is cross-site scripting (XSS) and how do you prevent it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'CSS','What is the BEM naming methodology? What do Block, Element, and Modifier mean?','BEM (**Block, Element, Modifier**) is a CSS class-naming convention for scalable, low-specificity styles.
- **Block**: a standalone, reusable component — `.card`
- **Element**: a part of a block — `.card__title` (double underscore)
- **Modifier**: a variant or state — `.card--featured`, `.card__title--large` (double hyphen)

Everything is a single flat class, so specificity stays low and names are self-documenting and conflict-free.','An element sits inside a nested block — say a menu inside a header. Would you name it `.header__menu__item`?','No — BEM elements never chain to mirror DOM depth (`block__el__el` is discouraged). Make the menu its own block: `.menu` with `.menu__item`. Names stay flat: one block + one element + optional modifier, no matter how deeply nested the markup is.','intermediate',ARRAY['bem','css-architecture','naming-conventions','specificity']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='CSS' AND q='What is the BEM naming methodology? What do Block, Element, and Modifier mean?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'CSS','What are CSS custom properties (variables)? How do you define, use, and give them a fallback?','User-defined variables prefixed with `--`, resolved by the browser at **runtime** (unlike Sass variables, which are compile-time).
- Define: `--main: blue;` (often on `:root` for global scope)
- Use: `color: var(--main);`
- Fallback: `var(--main, black)` uses `black` when `--main` is unset

They cascade and inherit like normal properties, are scoped to the element they''re set on and its descendants, and can be read/written from JS via `getPropertyValue` / `setProperty`.','If `--x: 10foo;` and you write `width: var(--x, 100px)`, does the box get `100px`?','No. The `var()` fallback applies only when the custom property is missing/empty as a variable — not when it holds a value that''s valid syntax but invalid for the target property. Here `--x` resolves fine, so `width` becomes **invalid at computed-value time (IACVT)** and falls back to `width`''s inherited or initial value (`auto`), not `100px`. A common footgun.','intermediate',ARRAY['custom-properties','css-variables','cascade','theming']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='CSS' AND q='What are CSS custom properties (variables)? How do you define, use, and give them a fallback?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'CSS','What''s the difference between a pseudo-class and a pseudo-element? Explain the syntax difference with examples.','- **Pseudo-class** (`:`) targets a real element in a certain **state** or position — `:hover`, `:focus`, `:nth-child(2)`, `:disabled`.
- **Pseudo-element** (`::`) styles a **part** of an element or injects a sub-element not in the DOM — `::before`, `::after`, `::first-line`, `::placeholder`, `::selection`.

Pseudo-classes use one colon, pseudo-elements two (`::`) in CSS3 (`:before`/`:after` still work for legacy). A selector may contain only one pseudo-element, and it must come last.','Why do `::before`/`::after` need a `content` property, and can you use them on an `<img>`?','`::before`/`::after` render only if `content` is set (even `content: ""`); with no `content` there''s no generated box. They generally don''t work on **replaced elements** like `<img>`, `<input>`, or `<br>` — such elements'' content comes from an external source and have no document children to wrap, so there''s nowhere to attach the generated content.','intermediate',ARRAY['pseudo-classes','pseudo-elements','selectors','content']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='CSS' AND q='What''s the difference between a pseudo-class and a pseudo-element? Explain the syntax difference with examples.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'CSS','How does z-index work, and what is a stacking context? Why can a higher z-index element still render behind another?','`z-index` sets the paint order of **positioned** elements — but only among elements in the **same stacking context**. A stacking context is a self-contained layer: z-index values compete only among siblings inside it, and the whole context paints as one unit at its own level in the parent.

So a child with `z-index: 9999` can sit behind another element when the child''s parent forms a stacking context that ranks below that element — a child can never paint above its parent''s layer.','Besides `position` + `z-index`, name properties that create a new stacking context on their own.','Many, including: `position: fixed`/`sticky`; `opacity` < 1; a non-`none` `transform`, `filter`, `perspective`, `clip-path`, or `mask`; `will-change` naming such a property; `isolation: isolate`; `mix-blend-mode` other than `normal`; a flex/grid child with a `z-index` other than `auto`; and `contain: paint`/`layout`/`content`/`strict`. `isolation: isolate` is the clean way to force one deliberately.','advanced',ARRAY['z-index','stacking-context','positioning','painting']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='CSS' AND q='How does z-index work, and what is a stacking context? Why can a higher z-index element still render behind another?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What are Web Components, and which three browser technologies make them up?','Native browser APIs for building **reusable, encapsulated custom elements** that work in any framework (or none). Three pillars:
- **Custom Elements** — define your own tags via JS classes with lifecycle callbacks.
- **Shadow DOM** — an encapsulated internal DOM subtree with scoped styles.
- **HTML Templates** (`<template>` + `<slot>`) — inert, reusable markup you clone and fill.

They interoperate and ship no runtime library.','Do you need all three APIs to build a Web Component?','No — they''re independent. You can register a custom element that renders into the light DOM with no shadow root, or use `<template>`/Shadow DOM without defining a custom element. The minimum is a class registered via `customElements.define()`.','intermediate',ARRAY['web-components','custom-elements','shadow-dom','encapsulation']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What are Web Components, and which three browser technologies make them up?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What lifecycle callbacks does a Custom Element have, and when does each fire?','Register a class extending `HTMLElement` with `customElements.define(''my-el'', MyEl)`. The browser calls:
- **`constructor`** — instance created; set initial state, attach a shadow root.
- **`connectedCallback`** — inserted into the DOM; do setup, add listeners, fetch.
- **`disconnectedCallback`** — removed from the DOM; tear down.
- **`attributeChangedCallback(name, old, new)`** — an *observed* attribute changed (needs a static `observedAttributes` array).
- **`adoptedCallback`** — moved into a new document.','Why put DOM setup in `connectedCallback` instead of the constructor?','In the constructor the element isn''t guaranteed to be in the DOM, can''t be relied on to have attributes/children, and is forbidden from adding attributes or children (it throws for the upgrade case). `connectedCallback` runs once it''s actually connected — and can run again on re-insertion — so it pairs cleanly with `disconnectedCallback` for setup/teardown.','intermediate',ARRAY['web-components','custom-elements','lifecycle','dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What lifecycle callbacks does a Custom Element have, and when does each fire?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What is the `<template>` element, and how is its content different from normal DOM?','`<template>` holds markup that the parser reads but does **not** render. Its contents are **inert** — images don''t load, scripts don''t run, media doesn''t play — and they live in a separate `DocumentFragment` exposed as `template.content`, not as ordinary child nodes. You instantiate it by cloning: `template.content.cloneNode(true)`, then inserting the clone. Ideal for repeated markup and Web Component templates.','How does `<template>` differ from a hidden element with `display:none`?','A `display:none` element is still live in the document — its resources load, its scripts run, and it''s matched by `querySelector`. `<template>` content is genuinely inert and parked in a separate fragment owned by a different document, so nothing loads or executes until you clone it into the live tree.','intermediate',ARRAY['template','web-components','document-fragment','dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What is the `<template>` element, and how is its content different from normal DOM?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What is the Shadow DOM, and how do you attach one?','It''s a **separate, encapsulated DOM subtree** attached to a host element via `host.attachShadow({ mode: ''open'' })`, which returns a **shadow root**. Markup inside is hidden from the document''s normal tree and query methods, and its styles are scoped — outside CSS doesn''t reach in and inside CSS doesn''t leak out. It''s how browsers hide the internals of native controls like `<video>` and `<input type=range>`, and how Web Components encapsulate their DOM and CSS.','What''s the difference between `open` and `closed` shadow mode?','With `open`, `host.shadowRoot` returns the root, so external JS can reach in. With `closed`, `host.shadowRoot` is `null` and only the reference returned by `attachShadow` can access it. `closed` isn''t a security boundary — the reference can be captured or leaked — it just discourages outside access.','intermediate',ARRAY['shadow-dom','web-components','encapsulation','dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What is the Shadow DOM, and how do you attach one?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What''s the difference between the Light DOM and the Shadow DOM?','- **Light DOM** — the ordinary DOM you author: a component''s children as written in the main document, fully visible to global CSS and `document.querySelector`.
- **Shadow DOM** — the component''s private internal tree, scoped away from global styles and queries.

Content a consumer passes as children lives in the light DOM but can be **projected** into the shadow tree through `<slot>` elements. So light DOM = what the user provides; shadow DOM = the component''s internal implementation.','If a component uses Shadow DOM, where do the children written between its tags actually live and get styled?','They stay in the **light DOM** — still children of the host in the main tree — and are projected into the matching `<slot>`. They render visually inside the shadow output but remain light-DOM nodes: the *page''s* CSS styles them, not the shadow root''s, except via the `::slotted()` selector.','intermediate',ARRAY['shadow-dom','light-dom','slots','web-components']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What''s the difference between the Light DOM and the Shadow DOM?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','How does the Shadow DOM encapsulate styles, and how can you still style across the boundary?','Styles in a shadow root are **scoped**: a `<style>` inside applies only within it, page selectors don''t match shadow elements, and shadow selectors don''t leak out. Crossing the boundary deliberately:
- **`:host`** / `:host(.sel)` — style the host from inside.
- **`::slotted(sel)`** — style top-level light-DOM nodes projected into a slot.
- **`::part(name)`** — style elements the component exposes via `part="name"`, from outside.
- **CSS custom properties** — they inherit through the boundary, making `var(--x)` the main theming hook.','Do inherited properties like `color` and CSS custom properties pierce the shadow boundary?','Yes. Shadow boundaries block *selectors*, not *inheritance* — inheritable properties (`color`, `font`, and any `--custom-property`) flow from the host''s context into the shadow tree. That''s by design: since outside selectors can''t target shadow internals, custom properties are the sanctioned channel for theming a component.','advanced',ARRAY['shadow-dom','encapsulation','css-custom-properties','web-components']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='How does the Shadow DOM encapsulate styles, and how can you still style across the boundary?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'HTML','What''s the difference between the `DOMContentLoaded` and `window` `load` events?','- **`DOMContentLoaded`** (on `document`) — fires once the HTML is fully parsed and the DOM tree is built (deferred scripts have run). It does **not** wait for stylesheets, images, or subframes. This is the "DOM is ready" signal.
- **`load`** (on `window`) — fires once the page **and all dependent resources** (images, stylesheets, iframes, fonts) have finished loading, often much later.

Wire DOM logic to `DOMContentLoaded`; use `load` only when you need final resource state, like image dimensions.','Does `DOMContentLoaded` wait for `async`/`defer` scripts or stylesheets?','It waits for `defer` scripts (they execute in order right before it fires) but not `async` scripts (which run whenever they arrive). It doesn''t wait for stylesheets directly — but a *synchronous* `<script>` after a `<link rel=stylesheet>` blocks on that CSS first (the script might read computed styles), which indirectly delays `DOMContentLoaded`.','intermediate',ARRAY['events','dom','page-lifecycle','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='HTML' AND q='What''s the difference between the `DOMContentLoaded` and `window` `load` events?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'TypeScript','What''s the difference between `type` and `interface` in TypeScript, and when would you pick one over the other?','Both describe the shape of objects and overlap heavily, but:

- **`interface`** supports *declaration merging* (same-name declarations combine) and is limited to object/function/class shapes.
- **`type`** aliases can represent *anything* — unions, intersections, tuples, primitives, mapped and conditional types — but cannot be reopened or merged.
- Both can extend (`interface extends`, `type` via `&`) and be implemented by classes.

Prefer `interface` for public/extensible object APIs (clearer errors, mergeable); reach for `type` when you need unions, tuples, or computed/mapped types.','Can a class `implements` a `type` alias, or does that only work with `interface`?','A class can implement a `type` alias as long as it resolves to a single object shape — e.g. `type Point = { x: number; y: number }` works with `implements`. It fails for union aliases (`type U = A | B`) because the shape isn''t determinate. Interfaces are always object shapes, so they''re always implementable.','intermediate',ARRAY['types','interfaces','type-aliases','declaration-merging']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='TypeScript' AND q='What''s the difference between `type` and `interface` in TypeScript, and when would you pick one over the other?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'TypeScript','What are generics in TypeScript, and what problem do they solve?','Generics let you parameterize code over types, so a function, class, or type can work with many types while preserving the relationships between them — without falling back to `any`. A type parameter (e.g. `function identity<T>(x: T): T`) is inferred from arguments or supplied explicitly, then flows through the signature so callers keep full type information. You can constrain parameters (`<T extends { id: number }>`) and give defaults (`<T = string>`). They power reusable structures like `Array<T>`, `Promise<T>`, and `Map<K, V>`.','How would you type `getProperty(obj, key)` so it returns the exact type of the requested property?','Constrain the key to `keyof` the object and use an indexed access type for the return:

```ts
function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}
```

`K extends keyof T` restricts `key` to valid property names, and `T[K]` resolves to that property''s value type — so `getProperty(user, ''age'')` is typed `number`, while an invalid key is a compile-time error.','intermediate',ARRAY['generics','type-parameters','constraints','keyof']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='TypeScript' AND q='What are generics in TypeScript, and what problem do they solve?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'TypeScript','What''s the difference between the `any` and `unknown` types in TypeScript?','Both can hold any value, but they differ in safety:

- **`any`** turns *off* type checking for that value — any property access, call, or assignment is allowed. It''s an escape hatch that silences the compiler.
- **`unknown`** is the type-safe top type: you can assign anything *to* it, but you can''t *use* it (property access, calls, assignment to a narrower type) until you prove its type with a guard (`typeof`, `instanceof`, `in`) or an assertion.

Prefer `unknown` for values of genuinely unknown type — `JSON.parse`, API payloads, `catch` errors — because it forces a check before use instead of silently propagating `any` through your codebase.','What type does the variable in a `catch (e)` block have, and how do you safely read `e.message`?','Under `strict` (TS 4.4+ `useUnknownInCatchVariables`), `e` is `unknown`, so you can''t touch `e.message` directly. Narrow first: `if (e instanceof Error) console.log(e.message)`, or check `typeof e === ''object'' && e !== null && ''message'' in e`. You may annotate `catch (e: unknown)` explicitly — `any` is the only other allowed annotation. Before 4.4, `e` was implicitly `any`.','intermediate',ARRAY['any','unknown','type-safety','type-narrowing']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='TypeScript' AND q='What''s the difference between the `any` and `unknown` types in TypeScript?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is React Fiber?','Fiber is the reconciliation engine introduced in React 16. It reimplements the reconciler so the work of rendering is represented as a linked list of "fiber" nodes (one per element) kept on the heap rather than the call stack. This lets React split rendering into units it can pause, resume, reuse, prioritize, and abort — the foundation for concurrent features like time-slicing and Suspense.','How does Fiber enable interruptible rendering that the old stack reconciler couldn''t?','The old reconciler recursed synchronously on the JS call stack — once it started, it ran to completion and blocked the main thread. Fiber keeps its own linked-list stack in memory, so React can process one fiber, yield to the browser via the scheduler, and resume later, making rendering interruptible.','advanced',ARRAY['fiber','reconciliation','concurrency','virtual-dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is React Fiber?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a React error boundary and how do you create one?','A component that catches JavaScript errors thrown while rendering, in lifecycle methods, and in constructors of its child tree, then renders a fallback UI instead of crashing the whole app. Only **class components** can be error boundaries — you implement `static getDerivedStateFromError` (to render the fallback) and/or `componentDidCatch` (to log). There is still no built-in Hook equivalent.','Which errors do error boundaries NOT catch?','Errors in event handlers, asynchronous code (`setTimeout`, promises), server-side rendering, and errors thrown in the boundary itself. Event handlers don''t run during rendering, so React can''t catch them there — wrap that logic in `try/catch` instead.','intermediate',ARRAY['error-boundaries','error-handling','class-components','lifecycle']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a React error boundary and how do you create one?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is React Suspense?','A mechanism that lets a component "suspend" rendering while it waits for something async and show the `fallback` from the nearest `<Suspense>` boundary meanwhile. Mechanically, a child throws a promise; React catches it, renders the fallback, and re-renders the subtree when the promise resolves. It''s stable today for `React.lazy` code-splitting and streaming SSR; Suspense-based data fetching is used through frameworks/libraries (and the `use()` hook in React 19).','Mechanically, how does a component tell Suspense to show the fallback?','It **throws a promise** instead of returning JSX. React catches the thrown promise at the nearest Suspense boundary, renders the fallback, subscribes to the promise, and retries rendering the subtree once it resolves. This throw-a-promise protocol is exactly how data libraries integrate with Suspense.','intermediate',ARRAY['suspense','code-splitting','concurrency','data-fetching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is React Suspense?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a React portal and when would you use one?','`createPortal(children, domNode)` renders children into a DOM node **outside** the parent''s DOM hierarchy while keeping them in the React tree. It''s used for modals, tooltips, and popovers that must escape a parent''s `overflow: hidden` or `z-index` stacking context, yet should still receive props and context from where they''re declared in the component tree.','If a portal renders outside the parent DOM, does an event fired inside it still bubble to the parent React component?','Yes. Event bubbling follows the **React tree**, not the DOM tree, so a click inside a portal bubbles up to ancestors in the React component tree even though the DOM node lives elsewhere. Context also flows down normally.','intermediate',ARRAY['portals','modals','event-bubbling','dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a React portal and when would you use one?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a Higher-Order Component (HOC)?','A function that takes a component and returns a new component with added behavior or props: `const withAuth = (Comp) => (props) => <Comp {...props} user={user} />`. It''s a pattern for reusing cross-cutting logic (auth, logging, data). Classic examples are Redux''s `connect` and the old `withRouter`. Largely superseded by custom Hooks for logic reuse.','Name two common pitfalls of HOCs that Hooks avoid.','"Wrapper hell" (many nested components cluttering the tree) and opaque/colliding props — you can''t tell where an injected prop came from, and two HOCs may inject the same name. You also have to hoist statics and forward refs manually. Hooks share logic without adding tree layers.','intermediate',ARRAY['hoc','composition','code-reuse','patterns']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a Higher-Order Component (HOC)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is the render props pattern?','A component takes a **function** as a prop (often `children` or `render`) and calls it with its internal state, letting the caller decide what to render: `<Mouse>{(pos) => <p>{pos.x}</p>}</Mouse>`. It shares stateful logic while giving the consumer full control of the output. Like HOCs, it''s largely replaced by custom Hooks.','What performance gotcha comes from passing an inline arrow as the render prop?','A new function is created on every render, so any memoization (`React.memo`, `PureComponent`) on the child breaks — props always look "changed," causing extra re-renders. Custom Hooks sidestep this because they return values instead of passing render-functions around.','intermediate',ARRAY['render-props','composition','code-reuse','patterns']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is the render props pattern?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a SyntheticEvent in React?','A cross-browser wrapper around the native DOM event with a normalized API (`preventDefault`, `stopPropagation`, `target`, …), so behavior is consistent across browsers. React attaches listeners via **delegation** — in React 17+ at the root container of your app (it was `document` in React 16). Handlers use camelCase, e.g. `onClick`.','React 16 sometimes needed `e.persist()` — why, and is it still needed?','React 16 **pooled** SyntheticEvents (reusing and nullifying them after the handler) for performance, so reading the event asynchronously required `e.persist()`. React 17 removed event pooling, so `persist()` is no longer necessary — it''s now a harmless no-op.','intermediate',ARRAY['synthetic-events','event-delegation','event-handling']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a SyntheticEvent in React?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Why does React need a `key` on list items?','Keys give list children a **stable identity** across renders so the reconciler can match old and new elements — reusing, reordering, or removing DOM and component state correctly instead of recreating everything. Without stable keys, React falls back to matching by array index, which breaks when items are inserted, removed, or reordered.','You render a list of inputs with `key={index}`, then delete the first item. What visibly breaks?','React matches by position, so each input''s component state (typed value, focus) stays attached to its **index**, not its data. Deleting the first row shifts every input''s state up by one, so values appear to jump to the wrong items. A stable unique id fixes it.','intermediate',ARRAY['keys','reconciliation','lists','virtual-dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Why does React need a `key` on list items?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Controlled vs uncontrolled components — what''s the difference?','A **controlled** component''s value lives in React state, driven by `value` + `onChange`, so React is the single source of truth. An **uncontrolled** component keeps its value in the DOM; you read it imperatively with a ref (and set an initial value via `defaultValue`). Controlled enables live validation and derived UI; uncontrolled is simpler and closer to plain HTML (and needed for file inputs).','What warning appears if you pass `value` without `onChange`, and why?','React warns you provided a `value` prop without an `onChange` handler, making the field read-only. Because `value` binds the input to state, with no `onChange` the state never updates, so the input appears frozen. Fix it with `onChange`, `readOnly`, or `defaultValue`.','intermediate',ARRAY['controlled-components','forms','state','refs']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Controlled vs uncontrolled components — what''s the difference?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What does "lifting state up" mean in React?','When two or more components need to share or stay in sync with the same data, you move that state to their **closest common ancestor** and pass it down as props (with callbacks to update it). The ancestor becomes the single source of truth, so siblings stay consistent instead of holding diverging copies.','What''s the main downside of lifting state up, and one way to mitigate it?','It can cause **prop drilling** (threading props through intermediate components) and re-render the whole subtree on each change. Mitigate with Context for widely-shared values, component composition via `children` to skip layers, or a state library with selectors for fine-grained subscriptions.','intermediate',ARRAY['lifting-state','state','props','data-flow']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What does "lifting state up" mean in React?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Why does React use one-way (unidirectional) data flow?','Data flows **down** from parent to child via props; children communicate **up** only through callbacks. This makes state changes predictable and traceable — for any piece of UI you can find the single owner of the data — and avoids the tangled, hard-to-debug update cycles of two-way binding, where any component can mutate shared state.','If data only flows down, how do children send data back up?','The parent passes down a **callback prop**; the child invokes it with data (e.g. `onChange(value)`). The parent owns the state, updates it, and the new value flows back down as props. Control still originates at the data''s owner, preserving the single direction.','intermediate',ARRAY['data-flow','props','state','architecture']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Why does React use one-way (unidirectional) data flow?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is prop drilling and how do you avoid it?','Passing a prop through several intermediate components that don''t use it themselves, just to reach a deeply nested consumer. It''s verbose and couples middle components to data they don''t care about. Fixes: **Context** for the subtree, **component composition** (pass JSX via `children`/slots so data stays where it''s created), or a state-management library.','How does component composition remove prop drilling without Context?','Instead of drilling data down, the owner renders the deep child itself and passes it in as `children` (or a prop element). The intermediate components just render `{children}` and never see the data — the JSX "hole" lets you inject a consumer already wired to its data.','intermediate',ARRAY['prop-drilling','context','composition','props']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is prop drilling and how do you avoid it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What''s the difference between React and React Native?','React is the core library for describing UIs as components. **React DOM** renders those to HTML/DOM in a browser; **React Native** uses the same React core but renders to **native mobile UI** via primitives like `<View>`/`<Text>` instead of `<div>`/`<span>`, styled with a JS `StyleSheet` (a flexbox subset) rather than CSS. The programming model — components, props, state, Hooks — is shared; the render target and primitives differ.','Can you reuse the same JSX components between a React web app and a React Native app?','Not the presentational ones — they use different primitives (`div` vs `View`) and styling (CSS vs `StyleSheet`). What you *can* share is non-UI logic: hooks, reducers, state, and API/business code. Libraries like React Native Web bridge the primitives to increase sharing.','intermediate',ARRAY['react-native','cross-platform','rendering']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What''s the difference between React and React Native?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What changed about state update batching in React 18?','React 18 introduced **automatic batching everywhere**. Multiple `setState` calls are grouped into a single re-render not just inside React event handlers (the React 17 behavior) but also in promises, `setTimeout`, native event handlers, and other async contexts. In React 17, updates outside React handlers weren''t batched, so each `setState` triggered its own render.','How do you force a synchronous, un-batched update in React 18 when you truly need one?','Wrap it in `flushSync(() => setState(...))` from `react-dom`. It commits that update synchronously — e.g. so you can read the updated DOM immediately — opting out of automatic batching. Use it sparingly, since it hurts performance by forcing an extra render/paint.','advanced',ARRAY['batching','react-18','rendering','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What changed about state update batching in React 18?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a stale closure in React, and when does it bite you?','Every render creates new functions that **close over** that render''s props and state. If a function captures a value but runs later — in an effect with missing deps, a handler set up once, a `setInterval`, or a memoized callback — it sees the **old** value from the render it was created in, not the current one. Classic case: `setInterval` inside `useEffect([])` reading state.','A `setInterval` in `useEffect([])` logs the same initial `count` forever. Two fixes?','(1) Use the **functional updater** so you never read the captured value: `setCount(c => c + 1)`. (2) Keep the latest value in a **ref** (`ref.current = count`) and read `ref.current` inside the interval. Adding `count` to the deps also works but recreates the interval on each change.','advanced',ARRAY['closures','hooks','use-effect','stale-closure']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a stale closure in React, and when does it bite you?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Why do all consumers of a Context re-render when its value changes?','When a Provider''s `value` changes (compared with `Object.is`), React re-renders **every** consuming component, regardless of whether it uses the part that changed — there''s no built-in selector or partial subscription. A frequent bug is passing a fresh object literal as `value` each render (`value={{user, setUser}}`), which changes identity every time and re-renders all consumers even when nothing meaningful changed.','A component reads Context, but a `React.memo` above it doesn''t stop its re-render. Why?','`useContext` subscribes the component **directly** to the context, and a context update bypasses props entirely. `React.memo` only short-circuits re-renders that come from a parent via props — it can''t block one triggered by a context value change. Splitting contexts or using a selector library is the fix.','advanced',ARRAY['context','re-renders','memoization','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Why do all consumers of a Context re-render when its value changes?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How do you stop unnecessary re-renders from a React Context?','- **Split contexts** so rarely-changing data (setters/dispatch) and frequently-changing data (state) live in separate providers.
- **Memoize the `value`** with `useMemo` so its identity is stable across renders.
- Pass **stable dispatch** (from `useReducer`) rather than new inline closures.
- For fine-grained subscriptions, use a selector-based store (Zustand, Redux, `use-context-selector`) instead of raw Context.','Why is splitting state and dispatch into two contexts so effective?','Components that only dispatch actions (never read state) subscribe to the **dispatch context**, whose value never changes — so they don''t re-render when state updates. Only components reading state subscribe to the state context. It separates "who triggers changes" from "who reacts to them."','advanced',ARRAY['context','performance','memoization','re-renders']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How do you stop unnecessary re-renders from a React Context?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','When should you NOT reach for Context?','Avoid Context for **high-frequency, large, or complex state** — since every consumer re-renders on any value change, it scales poorly for form fields, cursor position, or fast-updating app state. Don''t use it just to avoid passing one prop one level (composition is simpler), and don''t treat it as a full state manager — it has no selectors, middleware, or devtools. Prefer a dedicated store (Redux/Zustand/Jotai) or composition there.','Context is often called a dependency-injection tool, not a state-management tool. Why the distinction?','Context only **distributes** a value down the tree; it doesn''t store, update, or optimize state. You still need `useState`/`useReducer`/a store to hold and mutate the data. So Context answers "how do I get this value here," not "how do I efficiently store and update state."','intermediate',ARRAY['context','state-management','performance','architecture']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='When should you NOT reach for Context?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Describe the one-way data flow in Redux.','State lives in a single immutable **store**. The UI **dispatches** an action (a plain object describing what happened) → the **reducer** takes the current state + action and returns the next state → the store notifies subscribers → connected components read the new state and re-render. Data moves in one direction — view → action → reducer → store → view — and you never mutate state directly.','Why must this cycle be strictly one-directional?','A single, predictable update path makes every state change traceable to a dispatched action, enabling logging, replay, and time-travel debugging. Two-way binding would let views mutate state arbitrarily, reintroducing the tangled, non-deterministic updates Redux''s action log exists to prevent.','intermediate',ARRAY['redux','data-flow','state-management','actions']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Describe the one-way data flow in Redux.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Why must a Redux reducer be a pure function?','A reducer must (1) compute the next state solely from its `(state, action)` arguments, (2) never mutate the existing state (return a new object/array), and (3) have no side effects — no API calls, no `Date.now()`/`Math.random()`, no dispatching. Purity is what makes Redux predictable: the same state + action always yields the same result, enabling time-travel debugging, hot reloading, and easy testing.','Where should side effects like async API calls live if not in the reducer?','In **middleware** — thunks, sagas, RTK Query, or listener middleware. Middleware sits between `dispatch` and the reducer, performs the async work or side effect, and dispatches plain actions with the results, keeping reducers pure.','advanced',ARRAY['redux','reducers','purity','immutability']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Why must a Redux reducer be a pure function?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is a Redux thunk?','A thunk is a **function returned from an action creator** instead of a plain action object. With the `redux-thunk` middleware, `dispatch` accepts that function and calls it with `(dispatch, getState)`, letting you run async logic (API calls, conditional dispatches) and dispatch real actions when done. It''s the simplest way to handle side effects in Redux.','How does the store know to call your function instead of treating it as an action?','The `redux-thunk` middleware inspects each dispatched value: if it''s a **function**, the middleware invokes it with `(dispatch, getState)` and stops; otherwise it passes the plain action to the reducer. Without the middleware installed, dispatching a function throws, because actions must be plain objects.','intermediate',ARRAY['redux','thunks','middleware','async']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is a Redux thunk?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Redux Thunk vs Redux Saga — how do they differ?','Both are middleware for side effects. **Thunk** is minimal: you write async functions with promises/async-await — easy to learn, great for simple cases, but complex flows get messy. **Saga** uses ES **generators** and declarative effects (`call`, `put`, `takeLatest`) to model side effects as a separate, highly testable process — powerful for complex orchestration (cancellation, debouncing, concurrency) at the cost of a steeper learning curve and boilerplate.','Name a side-effect scenario where Saga is clearly nicer than Thunk.','Cancellable or racing flows — e.g. `takeLatest` automatically cancels a previous in-flight request when a new one starts (typeahead search), or `race`/`take` to cancel a task on user action. With thunks you''d manage flags/`AbortController` manually; sagas express it declaratively.','advanced',ARRAY['redux','sagas','thunks','async']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Redux Thunk vs Redux Saga — how do they differ?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Why does Redux require immutable state updates?','Redux and React-Redux detect changes by **reference equality** (`prevState !== nextState`), not deep comparison. If you mutate state in place, the reference stays the same, so `connect`/`useSelector` think nothing changed and skip the re-render — the UI goes stale. Immutable updates (new objects/arrays) also enable time-travel debugging, since previous states aren''t overwritten.','Redux Toolkit lets you write `state.value = 1` in reducers — doesn''t that break the rule?','No. RTK''s `createSlice`/`createReducer` wrap reducers in **Immer**, which records your mutations against a draft and produces a brand-new immutable state under the hood. You write mutation-style code; Immer returns a new object with a new reference, so change detection still works.','advanced',ARRAY['redux','immutability','immer','reference-equality']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Why does Redux require immutable state updates?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How does Zustand differ from Redux?','Both are external stores, but Zustand is far more minimal — no provider, no actions/reducers/dispatch ceremony, little boilerplate. You create a store hook (`create((set) => ({...}))`) and read state with **selectors** (`useStore(s => s.count)`) that subscribe fine-grained, so only components using a changed slice re-render. Redux offers more structure, strict conventions, a rich middleware ecosystem, and devtools/time-travel — better for large teams needing enforced patterns; Zustand favors speed and simplicity.','Zustand doesn''t wrap the app in a Provider — where does the state actually live?','In a **module-level store** created by `create()` — a closure holding the state and its subscribers, outside React. Components subscribe via the hook. Because it''s a plain singleton, you can even read/write it outside React with `useStore.getState()`/`setState()`; no Context provider needed.','intermediate',ARRAY['zustand','redux','state-management','selectors']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How does Zustand differ from Redux?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How does Zustand minimize re-renders?','Components subscribe with a **selector**: `useStore(s => s.user)`. On each store update Zustand runs your selector and re-renders only if the selected slice changed (by `Object.is` by default). Components that don''t select a changed value stay put — unlike raw Context, where every consumer re-renders. For selectors returning new objects/arrays, you supply a shallow-equality comparator to avoid false positives.','A selector `s => ({ a: s.a, b: s.b })` re-renders on every store change. Why, and the fix?','It returns a **new object** each call, so the default `Object.is` equality always sees a different reference and re-renders. Fix it with shallow equality — `useStore(selector, shallow)` or the `useShallow` wrapper — or select each field separately with its own hook call.','advanced',ARRAY['zustand','re-renders','selectors','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How does Zustand minimize re-renders?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How does client-side routing work with the History API?','A client router uses `history.pushState()`/`replaceState()` to change the URL **without a full page reload**, then renders the matching component in JS. It listens for the `popstate` event to react to browser back/forward navigation. So the URL and history stay correct, but navigation swaps components in place instead of fetching a new HTML document from the server.','Why do History-API routes 404 on refresh unless the server is configured?','On a hard refresh the browser requests that exact path (e.g. `/users/5`) from the server, which has no such file/route and returns 404. The SPA fix is a **catch-all rewrite** serving `index.html` for all paths so the client router can handle them. Hash routing (`/#/users/5`) avoids this since the server only ever sees `/`.','intermediate',ARRAY['routing','history-api','spa']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How does client-side routing work with the History API?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','In React Router, when do you use `useNavigate` vs the `<Navigate>` component?','`useNavigate` returns a function to navigate **imperatively** — call `navigate(''/home'')` in an event handler or after an async action (e.g. post-login). `<Navigate to="/login" />` navigates **declaratively** by rendering — return it from a component''s JSX to redirect during render (e.g. an auth guard). Rule of thumb: event/side-effect → `useNavigate`; render-time redirect → `<Navigate>`.','Why is calling `navigate()` directly in the component body (not in a handler/effect) a bug?','Navigating is a **side effect**; doing it during render triggers a router state update mid-render, and React warns "Cannot update a component while rendering a different component." Put it in a `useEffect`, or render `<Navigate>` instead, which the router performs safely as part of the render flow.','intermediate',ARRAY['routing','react-router','navigation']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='In React Router, when do you use `useNavigate` vs the `<Navigate>` component?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is route-based code splitting in React?','Splitting your bundle so each route''s component loads on demand rather than upfront. You wrap route components in `React.lazy(() => import(''./Page''))` and a `<Suspense fallback={...}>`, so the code for a route downloads only when the user navigates there. This shrinks the initial bundle and speeds up first load — routes are natural split points since users rarely need every page immediately.','What must wrap a `React.lazy` route, and what happens without it?','A `<Suspense>` boundary with a `fallback`. While the lazy chunk loads, the component **suspends**; with no Suspense ancestor React throws "A component suspended… no fallback UI was specified." The boundary shows the fallback (e.g. a spinner) until the chunk arrives.','intermediate',ARRAY['code-splitting','routing','lazy-loading','suspense']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is route-based code splitting in React?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is `<Outlet>` in React Router''s nested routes?','With nested routes, a parent route renders shared layout (nav, sidebar) and marks where the matched **child** route should appear using `<Outlet />`. As the URL changes, React Router swaps the child rendered into the outlet while the parent layout persists. It''s how you build persistent layouts with changing inner content.','How do you pass data from a layout route down to whatever renders in its `<Outlet>`?','`<Outlet context={value} />`, and the child reads it with the `useOutletContext()` hook. This gives layout-to-child communication without prop drilling, since the child isn''t a direct JSX child you could hand props to.','intermediate',ARRAY['routing','react-router','nested-routes','layouts']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is `<Outlet>` in React Router''s nested routes?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','React Query: what''s the difference between `staleTime` and `cacheTime` (`gcTime`)?','**staleTime** is how long fetched data is considered **fresh** — while fresh, React Query serves it from cache and won''t refetch on mount/focus (default `0`, i.e. immediately stale). **cacheTime** (renamed **gcTime** in v5) is how long an **inactive/unused** query''s data lingers in the cache before garbage collection (default 5 minutes). In short: staleTime controls refetching; gcTime controls memory retention once no component uses the query.','With `staleTime: 0` and `gcTime: 5min`, you unmount and quickly remount — do you see data instantly, and does it refetch?','Both. Within gcTime the cached data still exists, so React Query shows it **immediately** (no spinner). But since staleTime is 0 the data is stale, so it also fires a **background refetch** to update it — the classic stale-while-revalidate behavior.','advanced',ARRAY['react-query','caching','stale-time','data-fetching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='React Query: what''s the difference between `staleTime` and `cacheTime` (`gcTime`)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','When does React Query automatically refetch in the background?','For a **stale** query, React Query refetches on several triggers by default: component mount/remount, window refocus (`refetchOnWindowFocus`), network reconnect (`refetchOnReconnect`), and when the `queryKey` changes. It shows the cached stale data immediately and updates when the refetch resolves — a background refetch doesn''t drop you back to the loading state. Fresh queries (within `staleTime`) skip all these; every trigger is configurable.','During a background refetch, why doesn''t the loading spinner show again?','Because cached data already exists, so `isLoading` (`status === ''pending''`) stays false — it''s only true on the very first fetch with no data. A background refetch is surfaced via `isFetching`/`isRefetching` instead, so you can show a subtle indicator while still displaying the old data.','intermediate',ARRAY['react-query','refetching','caching','data-fetching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='When does React Query automatically refetch in the background?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is query invalidation in React Query?','Marking cached queries as **stale** (and refetching the active ones) so they update — typically after a mutation changes server data. You call `queryClient.invalidateQueries({ queryKey: [''todos''] })`, and any query whose key **prefix-matches** is invalidated. It''s the standard way to keep the cache in sync: mutate on the server, then invalidate the affected queries to pull fresh data.','Does `invalidateQueries([''todos''])` also invalidate `[''todos'', 5]`?','Yes — invalidation matches by key **prefix** (fuzzy match), so `[''todos'']` invalidates `[''todos'']`, `[''todos'', 5]`, `[''todos'', {status:''done''}]`, and so on. To target one exactly, pass `{ queryKey: [''todos'', 5], exact: true }`.','intermediate',ARRAY['react-query','invalidation','caching','mutations']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is query invalidation in React Query?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','React Query: `useQuery` vs `useMutation` — when do you use each?','`useQuery` is for **reading** server data (GET-like): it''s declarative, runs automatically, caches by `queryKey`, dedupes, and refetches. `useMutation` is for **writing** (create/update/delete): it doesn''t run automatically — you call `mutate()`/`mutateAsync()` imperatively — isn''t cached by a key, and exposes `onSuccess`/`onError`/`onSettled` callbacks where you typically invalidate related queries.','After a successful `useMutation`, how do you get the affected `useQuery` lists to reflect the change?','In the mutation''s `onSuccess`, either **invalidate** the relevant keys (`queryClient.invalidateQueries(...)`) to refetch, or **directly write** the cache with `queryClient.setQueryData(...)` (e.g. for optimistic updates). Invalidation is the simplest correct default.','intermediate',ARRAY['react-query','use-query','use-mutation','data-fetching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='React Query: `useQuery` vs `useMutation` — when do you use each?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','What is an optimistic update?','Updating the UI **immediately** as if a mutation succeeded — before the server confirms — for a snappy, latency-free feel (e.g. a like button toggling instantly). You apply the change locally, fire the request, and if it **fails you roll back** to the previous state; if it succeeds you keep it (and usually revalidate). It trades a small risk of rollback flicker for much better perceived performance.','In React Query, how do you implement optimistic updates with correct rollback?','In `useMutation`: `onMutate` cancels in-flight refetches (`cancelQueries`), snapshots the current cache (`getQueryData`), and optimistically writes the new value (`setQueryData`), returning the snapshot as context. `onError` restores that snapshot; `onSettled` invalidates the query to reconcile with server truth.','advanced',ARRAY['optimistic-update','react-query','mutations','caching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='What is an optimistic update?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','Redux Toolkit: when do you use RTK Query vs `createSlice`?','Use **`createSlice`** for **client state** you own — UI flags, form state, local domain logic — generating a reducer plus actions. Use **RTK Query** (`createApi`) for **server state** — data fetching and caching — it auto-generates hooks (`useGetXQuery`, `useAddXMutation`) and handles caching, deduping, invalidation, and loading/error states, so you don''t hand-write thunks and reducers for API data. Roughly: `createSlice` = local state, RTK Query = async server cache.','RTK Query is built on top of which Redux Toolkit primitives?','It''s built on `createSlice`/`createReducer` (with Immer) and `createAsyncThunk` under the hood — it generates a slice, reducer, actions, and middleware for you. So it''s not a separate paradigm; it''s a layer that auto-produces the Redux data-fetching boilerplate you''d otherwise write by hand.','intermediate',ARRAY['rtk-query','redux-toolkit','data-fetching','state-management']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='Redux Toolkit: when do you use RTK Query vs `createSlice`?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How does RTK Query cache and invalidate data?','RTK Query caches each request by a **serialized cache key** built from the endpoint name + arguments; identical concurrent requests are deduped into one entry. Invalidation uses a **tag** system: queries `provide` tags (e.g. `[''Post'']`) and mutations `invalidate` tags, so a mutation automatically refetches the queries that provided matching tags. Entries for queries with no subscribers are removed after `keepUnusedDataFor` seconds (default 60).','How does RTK Query know which cached queries to refetch after a mutation?','Through **tags**. Each query declares the tags it `provides`; each mutation declares the tags it `invalidates`. When a mutation with `invalidatesTags: [''Post'']` succeeds, RTK Query finds every active query that provided a `''Post''` tag and refetches it — no manual key tracking required.','advanced',ARRAY['rtk-query','caching','invalidation','data-fetching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How does RTK Query cache and invalidate data?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'React','How do you detect and prevent memory leaks in React?','Most leaks come from **uncleaned effects**: subscriptions, timers (`setInterval`), event listeners, or async work that resolves after unmount. **Prevent** them by returning a cleanup function from `useEffect` (remove listeners, `clearInterval`, `controller.abort()`). **Detect** them in Chrome DevTools'' Memory tab — take heap snapshots before/after repeatedly mounting-unmounting a component and look for retained detached DOM nodes or climbing listener counts, and watch the Performance monitor for a JS heap that keeps growing.','What''s a modern way to cancel a `fetch` in `useEffect` so a late response can''t set state after unmount?','Use an `AbortController`: create one in the effect, pass `controller.signal` to `fetch`, and call `controller.abort()` in cleanup. The pending request rejects with an `AbortError` (which you ignore), so no state update fires after unmount — and it also handles StrictMode''s extra dev mount/unmount cycle.','advanced',ARRAY['memory-leaks','use-effect','cleanup','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='React' AND q='How do you detect and prevent memory leaks in React?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','What is hydration?','Hydration is where React takes the static HTML the server sent and makes it interactive on the client: it renders the same component tree, **matches** (rather than recreates) the existing DOM nodes, and attaches event listeners, state, and effects. This gives a fast first paint from SSR/SSG while still ending up as a fully interactive React app.','What causes a hydration mismatch error?','The client''s first render produced different markup than the server sent — commonly from non-deterministic values (`Date.now()`, `Math.random()`), browser-only APIs (`window`, `localStorage`), or invalid HTML nesting. React 18+ warns and discards the server HTML for that subtree, re-rendering it on the client (a perf hit and possible flicker). Fix by making the render deterministic or deferring client-only values into `useEffect`.','intermediate',ARRAY['hydration','ssr','react','dom']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='What is hydration?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','Why can hydration be slow even though the HTML is already visible?','The page *looks* ready, but it isn''t interactive until the client downloads, parses, and executes the JS bundle, then walks the whole component tree to reattach listeners and rebuild state — essentially re-doing the server''s render work. This pass is typically blocking and scales with bundle and tree size, so a large app has a gap between "painted" and "interactive" (hurting TTI/INP) — the classic "uncanny valley."','How do React Server Components and streaming reduce hydration cost?','Server Components render only on the server and ship zero JS, so they''re never hydrated — only `"use client"` components are, shrinking both the bundle and the hydration tree. Streaming with `<Suspense>` plus React 18''s selective hydration lets parts hydrate independently and out of order, and React can prioritize the component the user just interacted with instead of blocking on the whole page.','advanced',ARRAY['hydration','performance','ssr','server-components']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='Why can hydration be slow even though the HTML is already visible?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','What''s the difference between server-side rendering (SSR) and client-side rendering (CSR)?','- **SSR**: the server builds full HTML per request and sends it; fast first contentful paint and SEO-friendly, then React hydrates for interactivity. Costs server compute/TTFB.
- **CSR**: the server sends a near-empty shell plus a JS bundle; the browser runs JS, fetches data, and renders the DOM. Slower first paint and weaker default SEO, but cheap servers and app-like navigation after load.','Where does static generation (SSG) fit in?','SSG renders the HTML at **build time** instead of per request, so pages are precomputed and served from a CDN — even faster TTFB than SSR and cacheable, but content is fixed until the next build (or an ISR revalidation). SSR is that same server rendering deferred to request time so it can use per-request data. CSR still layers on top of both: after the initial HTML loads, hydration and later navigation happen on the client.','intermediate',ARRAY['ssr','csr','ssg','rendering','seo']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='What''s the difference between server-side rendering (SSR) and client-side rendering (CSR)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','What is Incremental Static Regeneration (ISR)?','ISR lets statically generated pages be **regenerated in the background after deploy**, without rebuilding the whole site. You serve a cached static page and set a `revalidate` window (in seconds); once it expires, the next request serves the stale page while Next.js regenerates it on the server, then swaps in the fresh version (stale-while-revalidate). You get SSG''s CDN speed with near-fresh data, and it scales to huge sites.','How do you update an ISR page immediately instead of waiting for the timer?','Use **on-demand revalidation**: call `revalidatePath()`/`revalidateTag()` (App Router) or `res.revalidate(path)` (Pages Router) from a route handler/API route — typically triggered by a CMS webhook — to purge and regenerate specific pages instantly. For paths not built yet, `generateStaticParams` (or `getStaticPaths` with `fallback: ''blocking''`) generates and caches them on first request.','intermediate',ARRAY['isr','ssg','caching','revalidation']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='What is Incremental Static Regeneration (ISR)?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','In Next.js, what''s the difference between a static route and a dynamic route?','- **Static route**: a fixed path from folder/file names — `app/about/page.js` → `/about`, matching exactly one URL.
- **Dynamic route**: a bracketed segment that matches many URLs — `app/blog/[slug]/page.js` matches `/blog/hello`, `/blog/world`, exposing `params.slug`. Variants: `[...slug]` (catch-all) and `[[...slug]]` (optional catch-all).

Use dynamic routes when the path depends on data (ids, usernames, slugs).','Does a dynamic route like `[slug]` force per-request server rendering?','No — dynamic **routing** is separate from dynamic **rendering**. A `[slug]` route can still be prerendered to static HTML by exporting `generateStaticParams()` (App Router) or `getStaticPaths` (Pages Router). It only becomes dynamically rendered if it uses dynamic APIs like `cookies()`/`headers()`, reads `searchParams`, uses uncached data, or hits a param not covered by `generateStaticParams` (subject to `dynamicParams`).','beginner',ARRAY['routing','dynamic-routes','app-router','ssg']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='In Next.js, what''s the difference between a static route and a dynamic route?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Next.js','Why does `useEffect` never run during server-side rendering?','`useEffect` is designed to fire **after** the component commits to a real DOM — for subscriptions, timers, measurements, and browser-only work. During SSR, React only produces an HTML string; it runs render but never commits or executes the effect phase, so effects are skipped on the server and only run after hydration in the browser. This is intentional: it keeps SSR a pure, synchronous pass and guarantees effects have `window`/`document` available.','So how do you run code during SSR that affects the HTML, and what about `useLayoutEffect`?','Do it during render itself — or in a Server Component or a data function like `getServerSideProps`/an async component — since only render output becomes the SSR''d HTML; effects can''t change it. `useLayoutEffect` also doesn''t run on the server and React warns about it during SSR, so the common fix is the `useIsomorphicLayoutEffect` pattern (use `useLayoutEffect` on the client, `useEffect`/no-op on the server). For client-only values, read them in `useEffect` and set state so it applies after hydration.','intermediate',ARRAY['use-effect','hooks','ssr','react']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Next.js' AND q='Why does `useEffect` never run during server-side rendering?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What are the main stages of the browser''s rendering pipeline?','The browser turns markup and styles into pixels through a fixed sequence:
- **Parse HTML → DOM** tree.
- **Parse CSS → CSSOM** tree.
- **Render tree**: combine DOM + CSSOM into visible nodes with computed styles.
- **Layout (reflow)**: compute each box''s geometry and position.
- **Paint**: fill in pixels (text, colors, borders) into layers.
- **Composite**: assemble layers onto the screen (often GPU-assisted).','Where does JavaScript execution fit into this pipeline, and why can it block rendering?','A non-deferred `<script>` runs synchronously during HTML parsing, pausing DOM construction until it finishes downloading and executing — so it blocks the whole pipeline. Scripts can also force a synchronous layout ("forced reflow") by reading geometry like `offsetHeight` or `getBoundingClientRect` while there are pending style/DOM changes, making the browser run layout early and mid-frame.','intermediate',ARRAY['rendering','layout','painting','browser']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What are the main stages of the browser''s rendering pipeline?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What''s the difference between reflow (layout) and repaint, and why does it matter for performance?','- **Reflow (layout)**: recomputing element geometry and positions. Triggered by size/position/DOM-structure changes, and can cascade to ancestors and descendants — expensive.
- **Repaint**: redrawing pixels without changing geometry (color, `background`, `visibility`, `box-shadow`) — cheaper than reflow.

Changing only `transform` or `opacity` on a composited layer can skip both layout and paint, going straight to the compositor — which is why they animate smoothly.','What is "layout thrashing" and how do you avoid it?','Layout thrashing is repeatedly interleaving DOM writes with reads of layout properties (`offsetTop`, `getBoundingClientRect`, `scrollHeight`) in a loop. Each read forces the browser to synchronously flush a pending reflow to return an accurate value, so you pay for many layouts instead of one. Fix it by batching: do all reads first, then all writes (the read/write phase pattern), or use `requestAnimationFrame`/FastDOM to schedule writes.','intermediate',ARRAY['reflow','repaint','layout-thrashing','rendering']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What''s the difference between reflow (layout) and repaint, and why does it matter for performance?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is the critical rendering path and how do you optimize it?','The critical rendering path is the sequence of steps the browser must complete before it can render the initial view: build the DOM, build the CSSOM, form the render tree, run layout, and paint. CSS and synchronous JS are render-blocking. Optimize by minimizing and inlining critical (above-the-fold) CSS, deferring non-critical CSS/JS (`defer`/`async`), reducing transferred bytes (minify + compress), and cutting the number of critical resources and network round trips.','Why is CSS render-blocking, and how do you make non-critical CSS non-blocking?','The browser won''t paint until the CSSOM is complete, because painting with partial styles would cause a flash of unstyled/restyled content — so every stylesheet in `<head>` blocks the first paint. Make non-critical CSS non-blocking by inlining only the above-the-fold critical CSS and loading the rest asynchronously, e.g. `<link rel="preload" as="style" onload="this.rel=''stylesheet''">` or a `media` swap trick.','intermediate',ARRAY['critical-rendering-path','render-blocking','css','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is the critical rendering path and how do you optimize it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is a CDN and how does it improve frontend performance?','A **Content Delivery Network** is a globally distributed network of edge servers that cache and serve your static assets (JS, CSS, images, fonts, video) from a location physically close to each user. Benefits: lower latency (shorter round trips), reduced load on your origin server, higher availability and resilience, and often built-in compression, HTTP/2-3, TLS termination, and DDoS protection.','You shipped a fix, but users behind the CDN still get the old JS file. What''s happening and how do you fix it?','The old asset is still cached at CDN edge nodes (and in browsers) under the same URL, and hasn''t hit its TTL. The robust fix is content-hashed filenames (`app.9f2a1c.js`) so every build produces a new URL that can''t collide with the cached one, served with long `immutable` cache headers. For assets that must keep a stable URL (like `index.html`), give them a short/`no-cache` TTL and purge/invalidate the CDN cache on deploy.','beginner',ARRAY['cdn','caching','latency','edge']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is a CDN and how does it improve frontend performance?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','Walk through what happens during DNS resolution when a browser requests a domain.','DNS translates a hostname into an IP address before any connection can open. The browser checks its own cache, then the OS cache, then queries a **recursive resolver** (usually your ISP''s or a public one like 8.8.8.8). If not cached, the resolver walks the hierarchy: **root** nameserver → **TLD** nameserver (e.g. `.com`) → the domain''s **authoritative** nameserver, which returns the IP. Each level caches the answer for its TTL. Only after resolution can the TCP + TLS handshake begin.','How can DNS lookups hurt page-load performance, and how do you mitigate them?','The first request to each new origin pays a DNS round trip before anything downloads, and this compounds when a page pulls from many third-party domains. Mitigate by reducing the number of distinct origins, and by using resource hints: `<link rel="dns-prefetch">` to resolve a domain early and `<link rel="preconnect">` to also do the TCP/TLS handshake ahead of time for critical origins. TTL-based caching handles repeat lookups.','intermediate',ARRAY['dns','networking','preconnect','latency']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='Walk through what happens during DNS resolution when a browser requests a domain.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is HTTPS, and what does the TLS handshake establish?','HTTPS is HTTP carried over **TLS**, encrypting traffic between browser and server. The TLS handshake does three things: **authenticates** the server via its certificate (validated up a chain to a trusted CA), **negotiates** the protocol version and cipher suite, and **derives a shared symmetric session key** (via ephemeral Diffie–Hellman for forward secrecy) used to encrypt the actual data. The result provides confidentiality, integrity, and authentication.','How does TLS 1.3 improve performance over TLS 1.2?','TLS 1.3 cuts the full handshake from two round trips (1.2) down to one (1-RTT), and supports **0-RTT resumption** where a returning client sends encrypted "early data" with no handshake round trip at all. It also removed legacy/insecure ciphers, simplifying negotiation. The catch: 0-RTT early data is replayable by an attacker, so it must only carry idempotent, safe requests.','intermediate',ARRAY['https','tls','security','networking']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is HTTPS, and what does the TLS handshake establish?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','How do `Cache-Control` and `ETag` control HTTP caching?','- **`Cache-Control`** sets the policy: `max-age` (freshness lifetime in seconds), `no-cache` (may store but must revalidate before use), `no-store` (never cache), `public`/`private`, and `immutable`.
- **`ETag`** is a content fingerprint the server sends. When a cached copy goes stale, the browser revalidates with `If-None-Match: <etag>`; if unchanged the server replies `304 Not Modified` with no body, saving bandwidth.

So `max-age` avoids requests entirely while fresh, and the ETag makes the eventual revalidation cheap.','What''s the difference between `no-cache` and `no-store`?','`no-store` forbids caching altogether — nothing is written to any cache, and every request goes fully to the origin. `no-cache` *allows* storing the response but requires revalidation with the origin (via ETag/`Last-Modified`) before each reuse, so a `304` can still serve the already-stored bytes without re-downloading them. In short, `no-cache` means "cache but always revalidate," not "don''t cache."','intermediate',ARRAY['http-caching','cache-control','etag','performance']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='How do `Cache-Control` and `ETag` control HTTP caching?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is cache-busting and how is it typically implemented?','Cache-busting forces clients to fetch a fresh version of an asset that would otherwise be served from cache. The standard technique is **content hashing**: the build tool emits filenames like `main.9f2a1c.js` where the hash changes only when the file''s contents change. New content → new URL → guaranteed fresh download, while unchanged files keep their URL and stay cached. This pairs with aggressive `Cache-Control: max-age=31536000, immutable` headers on the hashed assets.','Why is hashing the filename better than appending a query string like `app.js?v=123`?','Content hashing changes the URL only when the bytes actually change, so unchanged chunks keep their cache entries across deploys (better long-term cache reuse), and the hash is generated automatically. Query-string versioning requires manually bumping the number, and some intermediate proxies/CDNs have historically ignored the query string when keying the cache, serving stale files. Hashed filenames are unambiguous and let you cache immutable assets forever while serving the HTML with a short TTL.','intermediate',ARRAY['cache-busting','caching','content-hash','build-tools']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is cache-busting and how is it typically implemented?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is a Progressive Web App and what capabilities define one?','A **PWA** is a website that uses modern web APIs to behave like an installed native app. The two core pieces are a **service worker** (a background script enabling offline support, caching, push, and background sync) and a **web app manifest** (metadata for installability — name, icons, theme, display mode). This unlocks offline/precached assets, home-screen installation, push notifications, and near-instant repeat loads — all while remaining a URL-addressable, progressively-enhanced website.','What role does the service worker play, and what''s a common caching pitfall with it?','A service worker sits between the app and the network, intercepting `fetch` events so it can serve cached responses (offline-first, cache-then-network, stale-while-revalidate, etc.). The classic pitfall is trapping users on a stale app shell: because the service worker and its caches persist, an overly aggressive cache can keep serving an old build indefinitely. Avoid it with versioned cache names, deleting old caches in the `activate` event, and using `skipWaiting`/`clients.claim` deliberately.','beginner',ARRAY['pwa','service-worker','offline','caching']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is a Progressive Web App and what capabilities define one?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What''s the difference between prefetching and prerendering a resource or page?','- **Prefetch** (`<link rel="prefetch">`) downloads a resource or route the user will *probably* need next and stores it in the cache at low priority — it does not parse or execute it.
- **Prerender** (now via the Speculation Rules API) goes further: it fetches *and fully renders* the likely next page in the background, so the eventual navigation is near-instant.

Prefetch saves the download; prerender saves download **and** render, at higher CPU/memory/bandwidth cost if the prediction is wrong.','How does `preload` differ from `prefetch`?','`preload` is for resources the **current** page needs — it fetches them early at **high** priority (e.g. a web font or hero image the CSS will request soon), affecting the ongoing navigation. `prefetch` is a **low**-priority hint for a **future** navigation, fetched during idle time. Misusing them is wasteful: preloading a next-page asset steals bandwidth from the current load, and prefetching a critical current-page asset is too low-priority to help.','advanced',ARRAY['prefetch','prerender','resource-hints','preload']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What''s the difference between prefetching and prerendering a resource or page?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is list virtualization (windowing) and what problem does it solve?','Virtualization renders only the list items currently visible in the viewport (plus a small overscan buffer) instead of the entire list, recycling and repositioning nodes as the user scrolls. This keeps the DOM node count small and roughly constant no matter how long the list is, avoiding the memory, layout, and paint cost of thousands of offscreen rows. Libraries: react-window, TanStack Virtual. A tall spacer element preserves the correct total scrollbar height.','What''s the main challenge when virtualizing a list of variable-height items?','The scroll container''s total height and every row''s offset depend on heights you don''t know until each row actually renders. You typically render items, measure them, cache the measured offsets, and continually correct the estimated total height — but if early estimates are wrong, correcting them can shift content and cause visible scroll-position jumps. Caching measured sizes and anchoring the scroll to a known item mitigates the jumpiness.','intermediate',ARRAY['virtualization','windowing','rendering','react']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is list virtualization (windowing) and what problem does it solve?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is Webpack and what is its core job?','Webpack is a **module bundler**. Starting from one or more entry points, it builds a dependency graph of every import (JS, CSS, images, fonts…), uses **loaders** to transform non-JS files into modules, runs **plugins** for broader build tasks, and emits optimized bundle files for the browser. Along the way it enables code splitting, tree shaking, hot module replacement, and asset optimization.','What''s the difference between a loader and a plugin in Webpack?','**Loaders** work at the individual-module level: they transform files as they''re imported (e.g. `babel-loader` transpiles JS, `css-loader` resolves `@import`/`url()`, `file-loader` handles assets). **Plugins** hook into the wider compilation lifecycle to do things loaders can''t — emitting extra files, injecting env vars, extracting CSS to separate files, generating the HTML shell (`HtmlWebpackPlugin`). Rule of thumb: loaders transform files, plugins act on the whole build/bundle.','beginner',ARRAY['webpack','bundler','build-tools','code-splitting']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is Webpack and what is its core job?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is Vite and how does its dev server differ from a traditional bundler?','Vite is a build tool whose dev server serves your source over **native ES modules** — it doesn''t bundle the app up front. The browser requests modules on demand and Vite transforms each just-in-time (via esbuild), so the dev server starts almost instantly regardless of app size and HMR stays fast. For production it bundles with **Rollup** (dependencies pre-bundled by esbuild). In short: unbundled ESM in dev, an optimized bundle in prod.','Why does Vite still pre-bundle dependencies with esbuild even in dev mode?','Two reasons. First, many npm packages ship CommonJS or fan out into hundreds of internal modules; pre-bundling with esbuild converts them to ESM and collapses them into a few files, avoiding a flood of individual HTTP requests that would otherwise choke the browser. Second, it caches these bundled deps so they aren''t re-processed on every reload. Your own application source stays unbundled and is served on demand.','intermediate',ARRAY['vite','esbuild','dev-server','build-tools']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is Vite and how does its dev server differ from a traditional bundler?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','Compare Webpack and Vite for a modern frontend project.','- **Dev startup / HMR**: Vite serves unbundled native ESM (esbuild-transformed) → near-instant cold start and fast HMR that don''t degrade as the app grows. Webpack bundles the whole app on start, so cold start and HMR slow with project size.
- **Production**: Vite bundles with Rollup; Webpack uses its own pipeline. Both tree-shake, code-split, and optimize.
- **Ecosystem / config**: Webpack is older, extremely configurable, with a vast battle-tested loader/plugin ecosystem; Vite favors sensible defaults and minimal config.

Vite is the common default for new apps; Webpack persists in large, legacy, or highly-customized builds.','Vite is fast in dev, but could dev/prod differences ever cause bugs?','Yes. Dev runs unbundled native ESM via esbuild while production is a Rollup bundle, so behavior can diverge: esbuild doesn''t type-check and doesn''t perfectly match every transform, tree-shaking and side-effect handling differ, and things like dynamic `import` globs and asset URL resolution behave differently. Code can work in dev and break in the built output, so you should still run and test the production build in CI.','intermediate',ARRAY['webpack','vite','build-tools','tooling']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='Compare Webpack and Vite for a modern frontend project.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is minification and what does it do to your code?','Minification strips bytes that don''t affect execution — whitespace, comments, and long local identifiers (shortened to `a`, `b`…) — plus safe rewrites like dead-code elimination and collapsing expressions. The output runs identically but is much smaller, reducing download and parse time. Tools: Terser or esbuild for JS, cssnano or Lightning CSS for CSS. It''s distinct from compression, which happens on the wire.','What''s the difference between minification and compression (gzip/brotli), and do you need both?','Minification rewrites the source into fewer characters at build time — the file on disk is permanently smaller. Compression (gzip/brotli) is applied by the server per response and transparently decompressed by the browser; the stored source is unchanged, just smaller over the wire. They''re complementary and stack: minify first, then serve the minified file compressed. Together they beat either alone because they exploit different kinds of redundancy.','beginner',ARRAY['minification','compression','bundle-size','build-tools']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is minification and what does it do to your code?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What are source maps and why are they useful?','A source map is a file that maps positions in a transformed bundle (minified/transpiled/compiled) back to the original source — original file names, lines, and columns. With source maps loaded, browser devtools and error-tracking services display your original code and readable stack traces instead of the mangled bundle, making it possible to debug production issues. They''re referenced by a `//# sourceMappingURL=` comment and fetched on demand by devtools.','Should you ship source maps to production, and what are the tradeoffs?','You can, but serving full source maps publicly exposes your original source to anyone who opens devtools. The common practice is to generate maps but not serve them publicly — upload them privately to your error monitor (Sentry, etc.) so stack traces stay readable while the maps aren''t exposed, or use `hidden-source-map` (map emitted, no reference comment). Serving them publicly is fine for open-source projects or when debuggability outweighs code secrecy.','intermediate',ARRAY['source-maps','debugging','build-tools','error-tracking']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What are source maps and why are they useful?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What roles do Jest and React Testing Library play in testing a React app?','**Jest** is the test runner and assertion/mocking framework: it discovers and executes tests, and provides `expect`, mocks, spies, fake timers, and coverage. **React Testing Library (RTL)** renders components into a (jsdom) DOM and gives you queries and user-interaction utilities to test them the way a user experiences them — by role, label, and text — rather than by implementation details. In short: Jest runs and asserts; RTL renders and queries. They''re used together.','What is RTL''s guiding philosophy, and how does it change how you query elements?','"The more your tests resemble the way your software is used, the more confidence they give you." So you query by what a user perceives — `getByRole`, `getByLabelText`, `getByText` — instead of test IDs, class names, or internal state. This makes tests resilient to refactors (renaming a prop or restructuring markup doesn''t break them) and doubles as an accessibility check, since role/label queries only find elements actually exposed to assistive technology.','beginner',ARRAY['testing','jest','react-testing-library','react']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What roles do Jest and React Testing Library play in testing a React app?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','Distinguish unit, integration, and end-to-end tests.','- **Unit**: tests a single function or component in isolation with dependencies mocked. Fast, numerous, pinpoints failures.
- **Integration**: tests several units working together (e.g. a form + its validation + a mocked API) to catch interface mismatches between them.
- **End-to-end (E2E)**: drives the real app in a real browser through full user flows against a real or near-real backend (Cypress, Playwright). Slowest but highest confidence.

The "testing pyramid" suggests many unit tests, fewer integration, and fewest E2E.','What is the "testing trophy" and how does it differ from the classic testing pyramid?','The testing trophy (popularized by Kent C. Dodds) reweights the pyramid so **integration tests are the largest layer**, arguing they give the most confidence per unit of effort for UI apps, on top of a static-analysis base (types + lint), with fewer pure unit tests and few E2E tests. The pyramid maximizes cheap, isolated unit tests; the trophy contends that for frontend work, integration tests best balance confidence, speed, and maintenance cost.','beginner',ARRAY['testing','unit-testing','integration-testing','e2e']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='Distinguish unit, integration, and end-to-end tests.');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is mocking in tests and when should you use it?','Mocking replaces a real dependency with a controlled fake so a test runs in isolation, deterministically, and fast. Use it for things that are slow, non-deterministic, or have side effects — network calls, timers, randomness, the filesystem, third-party SDKs. Related terms: a **stub** returns canned data, a **spy** records how a function was called, and a **mock** does both and often asserts on the interaction. Over-mocking, though, couples tests to implementation and lowers confidence.','What''s the risk of mocking too much, and what''s a better way to mock `fetch`?','Over-mocking makes tests verify your *assumptions* about a dependency rather than real behavior — they pass while the actual integration is broken, and break on every refactor. For network code, mock at the network boundary with a tool like **MSW (Mock Service Worker)**, which intercepts real requests and returns fixture responses. Your code still calls real `fetch`, so you exercise the true request/response path without coupling to `fetch`''s internals — and the same handlers work in tests and the browser.','intermediate',ARRAY['mocking','testing','stubs','msw']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is mocking in tests and when should you use it?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What do CI and CD mean, and what does a frontend pipeline typically run?','- **CI (Continuous Integration)**: every push is automatically built and tested so problems surface early. A frontend CI job usually runs install, lint, type-check, unit/integration tests, and a production build.
- **CD (Continuous Delivery/Deployment)**: automatically ships passing builds — *Delivery* produces a deploy-ready artifact awaiting a manual approval; *Deployment* pushes to production with no manual gate.

The goal is fast, reliable, repeatable releases with quick feedback on each change.','What''s the difference between Continuous Delivery and Continuous Deployment?','Both automate everything up to production. **Continuous Delivery** stops at a tested, deploy-ready artifact and requires a human to click "release" (a manual gate for business or QA reasons). **Continuous Deployment** removes that gate — every change that passes the pipeline goes straight to production. Deployment demands very high confidence in the test suite and usually pairs with feature flags, canary/gradual rollouts, and fast automated rollback.','beginner',ARRAY['ci-cd','automation','deployment','tooling']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What do CI and CD mean, and what does a frontend pipeline typically run?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What''s the difference between ESLint and Prettier, and how do they work together?','**ESLint** is a linter: it statically analyzes code for problems — likely bugs, anti-patterns, and code-quality rules (unused vars, missing hook deps) — and can auto-fix many. **Prettier** is an opinionated **formatter**: it reprints code to a consistent style (spacing, quotes, line width) without judging correctness. Best practice: let Prettier own formatting and ESLint own code quality, disabling ESLint''s stylistic rules (via `eslint-config-prettier`) so the two don''t conflict.','Why is it recommended to turn off ESLint''s formatting rules when using Prettier?','Otherwise the two tools fight: ESLint''s stylistic rules (`quotes`, `indent`, `semi`) may flag or auto-fix code in ways that directly contradict how Prettier reformats it, producing conflicting fixes and noisy errors. `eslint-config-prettier` disables all of ESLint''s formatting-related rules, leaving ESLint to catch genuine code-quality and correctness issues while Prettier handles layout. Each tool owns exactly one concern, so they stop overlapping.','beginner',ARRAY['eslint','prettier','linting','tooling']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What''s the difference between ESLint and Prettier, and how do they work together?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','How should a frontend store and manage authentication tokens?','After authenticating, the client must carry a credential on requests, and where you store it is a security tradeoff:
- **`httpOnly`, `Secure` cookie**: not readable by JS (immune to token theft via XSS) and sent automatically — but requires CSRF defenses (`SameSite`, anti-CSRF tokens).
- **`localStorage` / in-memory**: easy to attach as an `Authorization` header and inherently CSRF-proof, but readable by any injected script (XSS risk).

The prevailing recommendation: short-lived tokens in `httpOnly` cookies (or an access token in memory + a refresh token in an httpOnly cookie), HTTPS everywhere, and never trusting the client — the server authorizes every request.','Why is storing a JWT in `localStorage` considered risky, and what''s the common alternative?','`localStorage` is readable by any JavaScript running on the page, so a single XSS hole — including a compromised third-party script — can exfiltrate the token and let an attacker impersonate the user from anywhere. The common alternative is an `httpOnly`, `Secure`, `SameSite` cookie that JS can''t read, often split into a short-lived access token plus a revocable refresh token, accepting that you now need CSRF protection. There''s no perfectly safe client storage; you''re choosing which attack (XSS vs CSRF) to defend against.','advanced',ARRAY['authentication','security','jwt','cookies']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='How should a frontend store and manage authentication tokens?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','Are OAuth and JWT competing choices? How do they relate?','They solve different problems and frequently coexist. **OAuth 2.0** is an *authorization framework* — a protocol by which a user grants an app delegated access ("log in with Google") and the app receives tokens without ever handling the user''s password. **JWT (JSON Web Token)** is a *token format* — a signed, self-contained JSON payload carrying claims (identity, permissions). OAuth flows can issue tokens that happen to be JWTs, but they could use opaque tokens instead, and JWTs are used well outside OAuth. "OAuth vs JWT" compares a framework with a format.','What''s a key security consideration when using JWTs as sessions, especially around revocation?','A signed JWT is stateless and self-validating, so the server trusts it until it expires — you can''t easily revoke a single token (logout, ban, key compromise) without adding server-side state, which undercuts the stateless benefit. Mitigations: keep access tokens short-lived with revocable refresh tokens, or maintain a denylist/token-version check. Also always validate the `alg` header (reject `none` and RS256↔HS256 confusion attacks) and never store secrets in the payload — JWTs are signed but not encrypted, so anyone can base64-decode and read them.','advanced',ARRAY['oauth','jwt','authentication','security']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='Are OAuth and JWT competing choices? How do they relate?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What are the main security concerns when building a single-page application?','- **XSS** is the biggest risk: SPAs render lots of dynamic content, so never inject unsanitized HTML (`dangerouslySetInnerHTML`), rely on framework escaping, and add a Content Security Policy.
- **Token/session storage**: prefer `httpOnly` cookies over `localStorage` to limit XSS token theft; guard cookies against CSRF.
- **Never trust the client**: all validation and authorization must be enforced server-side — hiding a button doesn''t protect an endpoint.
- Also: HTTPS everywhere, careful CORS config, dependency/supply-chain hygiene, and keeping secret API keys on the backend.','Since all SPA source is downloaded to the browser, how do you protect secrets and enforce authorization?','You don''t put secrets in the SPA at all — anything shipped to the browser (API keys, role checks, business logic) is fully visible and editable by the user, so client-side auth checks are UX only, never security. Real authorization lives on the server: every API endpoint independently authenticates and authorizes each request. Third-party secrets are proxied through your backend so the key never reaches the client; only publishable/public keys (e.g. Stripe''s) are ever safe to embed.','advanced',ARRAY['security','spa','xss','csp']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What are the main security concerns when building a single-page application?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','How would you design a robust component for uploading large files?','Key concerns:
- **Chunked/resumable upload**: split the file with `File.slice`, upload chunks (serial or limited-parallel), and resume only failed chunks (via S3 multipart or a protocol like tus) so a dropped connection doesn''t restart from zero.
- **Progress & control**: report per-chunk and overall progress; support pause/cancel/retry with `AbortController`.
- **Offload work**: hash or compress in a **Web Worker** to keep the UI responsive; upload direct-to-storage via presigned URLs to bypass your server.
- **Validation & UX**: check type/size on the client (and always on the server), cap concurrency, and handle network changes and backpressure.','Why upload directly to object storage with presigned URLs instead of through your own API server?','Routing large files through your app server turns it into a bandwidth and memory bottleneck and a single point of failure — it must buffer or stream every byte and scales poorly under many concurrent uploads. With a presigned URL, your backend only issues a short-lived, permission-scoped URL and the browser uploads bytes straight to S3/GCS, which is built for that throughput and natively supports multipart/resumable transfers. Your server stays lightweight (auth, issuing URLs, recording metadata on completion), offloading cost, scaling, and reliability to the storage service.','advanced',ARRAY['file-upload','chunking','web-workers','architecture']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='How would you design a robust component for uploading large files?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','How do you structure a large React codebase to keep it maintainable?','Prefer organizing **by feature/domain** over by file type:
- **Feature folders**: each feature owns its components, hooks, state, API calls, and tests, exposing a small public API via an `index`. Shared primitive UI and utilities live in a common layer.
- **Enforce boundaries**: keep dependencies flowing one way (features → shared, not feature → feature); some teams adopt conventions like Feature-Sliced Design.
- Co-locate related code, keep components small and typed, centralize cross-cutting concerns (routing, data fetching, error boundaries), and lazy-load routes for code splitting.

The goal is high cohesion, low coupling, and easy discoverability as the team grows.','Why is organizing by feature usually preferred over by file type (all components in one folder, all hooks in another) at scale?','Type-based folders (`/components`, `/hooks`, `/utils`) scale poorly because working on one feature means hopping across many directories, and nothing signals which files belong together or are safe to delete. Feature-based structure co-locates everything a feature needs, so changes stay local, ownership and boundaries are clear, dead code is obvious when a feature is removed, and features can be lazy-loaded as units. It optimizes for how teams actually work — by feature, not by artifact kind — reducing coupling and merge conflicts as the codebase grows.','intermediate',ARRAY['architecture','react','project-structure','scalability']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='How do you structure a large React codebase to keep it maintainable?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What is micro-frontend architecture and what problem does it solve?','Micro-frontends split a frontend into independently developed, deployed, and owned pieces (by team or domain) that compose into a single app — extending the microservices idea to the UI. The payoff is organizational: many teams ship autonomously, can mix frameworks/versions, and scale independently. Integration approaches include build-time packages, server-side composition, iframes, and runtime composition via **Module Federation** or web components. Costs include operational complexity, duplicated shared dependencies, and styling/state consistency.','What are the main downsides of micro-frontends, and when are they not worth it?','The big costs are bundle bloat and inconsistency: each app may ship its own copy of React and dependencies unless you share singletons (which reintroduces coupling), plus divergent styling, duplicated logic, cross-app state/routing coordination, and heavier ops/observability. They''re usually not worth it for a single small team or a modest app, where the overhead outweighs the benefit. They pay off mainly at organizational scale, where many teams need independent deployment on a large product — otherwise a well-structured modular monolith is the better default.','advanced',ARRAY['micro-frontends','architecture','module-federation','scalability']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What is micro-frontend architecture and what problem does it solve?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What are feature flags and how are they used on the frontend?','Feature flags (toggles) are runtime conditionals that turn functionality on or off **without a redeploy**. Common uses: decouple deploy from release (ship dark code, enable later), gradual/percentage rollouts and canaries, A/B experiments, targeting by user/segment/plan, kill switches to instantly disable a broken feature, and trunk-based development (merge incomplete work behind a flag). A flag service delivers values to the client, with targeting rules evaluated server-side or in an SDK.','What are the risks and hidden costs of feature flags, and how do you manage them?','Flags add combinatorial complexity — many flags create an exponential number of untested code-path combinations — and stale flags become permanent dead code and tech debt if never removed. Frontend-specific pitfalls: evaluating flags client-side can leak unreleased features (users inspect the bundle/network), and async flag loading causes flicker or a wrong initial render. Manage them by keeping flags short-lived with a removal/expiry process, evaluating sensitive gating server-side, and loading flags before first paint (or via SSR) to avoid flicker.','intermediate',ARRAY['feature-flags','deployment','experimentation','architecture']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What are feature flags and how are they used on the frontend?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','What are the key considerations when building a reusable component library / design system?','- **API design**: composable, predictable props; favor composition (compound components, `children`) over a boolean-prop explosion; support controlled/uncontrolled use and sensible defaults.
- **Theming/tokens**: drive color, spacing, and typography from design tokens (CSS variables) so consumers theme without forking.
- **Accessibility**: keyboard, focus management, and ARIA baked in — often via headless primitives (Radix, React Aria).
- **Distribution**: semver, tree-shakeable ESM builds, strong types, and docs/examples (Storybook).
- **Governance**: contribution guidelines, visual-regression tests, and a clear deprecation policy.','Why favor composition (compound components) over adding more boolean props to configure a component?','Piling on boolean/config props produces a combinatorial, rigid API: props interact in conflicting ways (`isLoading` + `isDisabled` + `variant`…), the component fills with conditionals, and every new use case forces a library change. Composition — exposing subcomponents (`<Menu><Menu.Item/></Menu>`) or accepting `children`/render props — pushes structure and layout decisions to the consumer, so the library stays small and flexible and covers cases you never anticipated. The tradeoff is a slightly more verbose call site and the need to design good sub-component contracts.','advanced',ARRAY['component-library','design-system','api-design','accessibility']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='What are the key considerations when building a reusable component library / design system?');

INSERT INTO submissions (cat,q,a,fq,fa,difficulty,tags,status,source)
SELECT 'Performance','How would you handle real-time data updates in a dashboard UI?','- **Transport**: pick by need — **WebSockets** for low-latency bidirectional streams, **Server-Sent Events** for simple one-way server→client updates (auto-reconnect, plain HTTP), or polling/long-polling as a fallback.
- **Performance**: batch/throttle/debounce high-frequency updates and coalesce them into animation frames instead of re-rendering per message; virtualize long tables; update only the changed slice of state.
- **Robustness**: reconnect with backoff, resync/backfill missed data on reconnect, and surface connection status.
- **Correctness**: dedupe and order messages, apply optimistic updates carefully, and bound buffers to avoid memory growth.','A stream pushes hundreds of updates per second and the UI becomes janky. How do you keep it responsive?','Decouple the data rate from the render rate. Buffer incoming messages (in a ref/queue) and flush the merged result on a schedule — e.g. once per `requestAnimationFrame` or every N ms — so you render at ~60fps instead of per message. Coalesce updates to the same entity (keep only the latest), update just the changed rows rather than the whole dataset, and virtualize the visible list so DOM work stays bounded. Offload heavy parsing/aggregation to a Web Worker. The core idea: many messages collapse into one batched, throttled render.','advanced',ARRAY['real-time','websockets','performance','dashboards']::text[],'approved','core'
WHERE NOT EXISTS (SELECT 1 FROM submissions WHERE source='core' AND cat='Performance' AND q='How would you handle real-time data updates in a dashboard UI?');
